// Generated by scripts/build_kg.py - do not edit by hand
window.KG_DATA = {"strands": {"num": "Numbers & Operations", "alg": "Algebra, Sets & Functions", "geo": "Geometry", "mea": "Measurement & Mensuration", "dat": "Data, Statistics & Probability", "tri": "Trigonometry", "cal": "Calculus", "vec": "Vectors & 3D Geometry"}, "nodes": [{"id": "g1.num.counting-to-9", "title": "Counting and Numbers 1–9", "grade": 1, "strand": "num", "description": "Counting tells us how many things there are. We say one number name for each object, and the last number we say tells the size of the whole group. This idea — that numbers stand for 'how many' — is the foundation of all arithmetic.", "prereqs": [], "outcomes": ["Can count up to 9 objects, touching each object exactly once", "Can say how many objects there are after counting, without recounting", "Can recognise and write the numerals 1 to 9", "Can count out a requested number of objects from a larger pile"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": []}, {"id": "g1.num.zero", "title": "Zero and Its Meaning", "grade": 1, "strand": "num", "description": "Zero is the number that tells us there is nothing to count. It is a real number with its own symbol, 0, and its own place on the number line just before 1. Understanding zero prepares us for place value and for adding and subtracting.", "prereqs": ["g1.num.counting-to-9"], "outcomes": ["Can say that zero means 'none' and write the numeral 0", "Can place 0 correctly before 1 when ordering numbers", "Can answer 'how many' questions where the answer is zero", "Can add and take away zero from a small number correctly"], "difficulty": 1, "est_minutes": 15, "stub": false, "micros": []}, {"id": "g1.num.numbers-to-20", "title": "Numbers up to 20", "grade": 1, "strand": "num", "description": "The numbers 10 to 20 are our first step beyond one hand and one foot of counting! Each 'teen' number is really a ten and some more — 14 is 10 and 4. Seeing this hidden ten is the first big idea of place value.", "prereqs": ["g1.num.counting-to-9", "g1.num.zero"], "outcomes": ["Can count objects up to 20 accurately", "Can read and write numerals 10 to 20 and say them in order", "Can show a teen number as one group of ten and some ones", "Can say which of two numbers up to 20 is more"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g1.num.add-sub-within-20", "title": "Addition and Subtraction within 20", "grade": 1, "strand": "num", "description": "Adding means putting groups together; subtracting means taking away or finding how many more. With numbers up to 20 we learn smart moves like counting on from the bigger number and making a ten. These small facts become the building blocks for all bigger sums.", "prereqs": ["g1.num.numbers-to-20"], "outcomes": ["Can add two numbers with a total up to 20 using objects, fingers or counting on", "Can subtract within 20 by taking away or counting back", "Can solve simple story problems about joining and taking away", "Can find the missing number in facts like 9 + __ = 15"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g1.num.numbers-to-99", "title": "Numbers up to 99: Tens and Ones", "grade": 1, "strand": "num", "description": "Big numbers are built from groups of ten. In the number 47, the 4 stands for 4 tens (forty) and the 7 stands for 7 ones. Once you can see tens and ones inside a number, you can read, write and compare any number up to 99.", "prereqs": ["g1.num.numbers-to-20"], "outcomes": ["Can count to 99 including across decade numbers (39 to 40, 59 to 60)", "Can say how many tens and ones are in any 2-digit number", "Can read and write 2-digit numbers from words and bundles", "Can skip count by tens (10, 20, 30, ...)"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g1.num.money-intro", "title": "Money: Recognising Coins and Notes", "grade": 1, "strand": "num", "description": "Money comes as coins and notes, and each one has a value printed on it — ₹1, ₹2, ₹5, ₹10 and more. The value is what matters, not the size or the number of pieces. Knowing coins and notes lets us buy things and count small amounts.", "prereqs": ["g1.num.numbers-to-20"], "outcomes": ["Can name the common coins (₹1, ₹2, ₹5, ₹10) and notes (₹10, ₹20, ₹50)", "Can compare two coins or notes by value using the printed number", "Can find the total of two or three small coins and notes", "Can show the same amount using different coins"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": []}, {"id": "g1.geo.shapes-around-us", "title": "Shapes Around Us: Solids and Flat Shapes", "grade": 1, "strand": "geo", "description": "Everything around us has a shape. Solid objects like balls, boxes and cans can roll, slide or stack, while flat shapes like circles, triangles, squares and rectangles live on paper and on the faces of solids. Naming and sorting shapes trains us to see the world like a mathematician.", "prereqs": [], "outcomes": ["Can name circle, triangle, square and rectangle in any size or turn", "Can sort everyday objects by whether they roll, slide or stack", "Can tell a flat (2D) shape from a solid (3D) object", "Can find shapes hiding in everyday things (a roti is round, a door is a rectangle)"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g1.mea.compare-lengths", "title": "Comparing Length, Weight and Capacity", "grade": 1, "strand": "mea", "description": "We compare things all the time: which pencil is longer, which bag is heavier, which glass holds more. To compare fairly we must line things up from the same end, feel or balance their weight, and pour to check what holds more. Careful comparing is the first step of all measurement.", "prereqs": [], "outcomes": ["Can use the words longer/shorter, taller/shorter, heavier/lighter, holds more/holds less correctly", "Can compare two lengths by lining objects up from the same end", "Can guess and then check which of two objects is heavier", "Can order three objects by length"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g1.mea.time-day-events", "title": "Time: Day, Night and Ordering Events", "grade": 1, "strand": "mea", "description": "Our day has a rhythm: morning, afternoon, evening and night, and things happen in an order — we wake up before we go to school. Talking about before, after, day and night, and which activity takes longer is how we begin to understand time.", "prereqs": [], "outcomes": ["Can name the parts of the day (morning, afternoon, evening, night) and match activities to them", "Can put 3-4 daily events in the right order using before and after", "Can use yesterday, today and tomorrow correctly in conversation", "Can say which of two activities takes longer"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": []}, {"id": "g1.alg.patterns-repeat", "title": "Repeating Patterns", "grade": 1, "strand": "alg", "description": "A repeating pattern is made of a small unit that comes again and again, like red-blue, red-blue. If you can find the unit, you can say exactly what comes next — that is the power of a pattern. Spotting and extending patterns is the very beginning of algebraic thinking.", "prereqs": [], "outcomes": ["Can copy and extend a repeating pattern of colours, shapes, sounds or actions", "Can point out the unit that repeats in a pattern", "Can create an own repeating pattern and explain its rule", "Can tell a real pattern from a random arrangement"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": []}, {"id": "g1.dat.sort-classify", "title": "Sorting and Classifying Objects", "grade": 1, "strand": "dat", "description": "Sorting means putting things into groups by a rule — by colour, by shape, by size, or by what they are used for. The same objects can be sorted in different ways, but within one sort the rule must stay the same. Sorting is how we begin to organise information, the first step towards handling data.", "prereqs": [], "outcomes": ["Can sort a set of objects by a given rule (colour, shape, size, use)", "Can state the rule used to sort a given group of objects", "Can re-sort the same objects using a different rule", "Can say which group has more or fewer objects after sorting"], "difficulty": 1, "est_minutes": 20, "stub": false, "micros": []}, {"id": "g2.num.place-value-2digit", "title": "Place Value: Comparing and Ordering to 99", "grade": 2, "strand": "num", "description": "A digit's value depends on WHERE it sits: in 47, the 4 means forty. To compare two numbers we look at the tens first, and only if the tens match do we check the ones. This lets us order any set of numbers up to 99 with certainty.", "prereqs": ["g1.num.numbers-to-99"], "outcomes": ["Can write any 2-digit number in expanded form (47 = 40 + 7)", "Can compare two 2-digit numbers by checking tens first, then ones", "Can order three or more numbers from smallest to greatest and greatest to smallest", "Can find the number that is 1 more, 1 less, 10 more or 10 less than a given number"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g2.num.numbers-to-999", "title": "Numbers up to 999: Hundreds", "grade": 2, "strand": "num", "description": "After tens come hundreds: ten tens bundle into one hundred. A 3-digit number like 407 has hundreds, tens and ones — and a zero can hold a place to show 'no tens'. With hundreds we can count, read and compare numbers all the way to 999.", "prereqs": ["g2.num.place-value-2digit"], "outcomes": ["Can explain that 10 tens make 1 hundred", "Can read and write 3-digit numbers from words and from hundreds-tens-ones", "Can write a 3-digit number in expanded form (263 = 200 + 60 + 3)", "Can compare and order 3-digit numbers by checking hundreds first"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g2.num.add-sub-2digit", "title": "2-digit Addition and Subtraction with Regrouping", "grade": 2, "strand": "num", "description": "When we add and the ones spill over ten, we bundle them into a new ten — that is carrying. When we subtract and the ones are not enough, we open up a ten — that is borrowing. Regrouping lets us add and subtract any numbers up to 99 quickly and correctly.", "prereqs": ["g1.num.add-sub-within-20", "g2.num.place-value-2digit"], "outcomes": ["Can add two 2-digit numbers with and without carrying", "Can subtract 2-digit numbers with and without borrowing", "Can explain regrouping using bundles of tens and ones", "Can check an answer using estimation or the opposite operation", "Can solve one-step story problems involving 2-digit addition and subtraction"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g2.num.mult-intro", "title": "Multiplication as Equal Groups and Repeated Addition", "grade": 2, "strand": "num", "description": "Multiplication is a shortcut for adding the same number again and again. '3 × 4' means 3 equal groups of 4 — like 3 plates with 4 laddoos each — and equals 4 + 4 + 4. Arrays of rows and columns show why 3 × 4 and 4 × 3 give the same total.", "prereqs": ["g1.num.add-sub-within-20"], "outcomes": ["Can describe a multiplication like 3 × 4 as '3 groups of 4'", "Can write repeated addition (5 + 5 + 5) as multiplication (3 × 5) and back", "Can find totals of equal groups by skip counting", "Can arrange objects in rows and columns (arrays) and count them two ways"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g2.num.money-transactions", "title": "Money: Simple Totals and Change", "grade": 2, "strand": "num", "description": "Shopping is maths in action: we add prices to find the total, and when we pay with a bigger note, we get change — the difference between what we gave and what it cost. We can also make the same amount in many ways using different coins and notes.", "prereqs": ["g1.num.money-intro", "g2.num.add-sub-2digit"], "outcomes": ["Can add two or three prices to find a total up to ₹99", "Can work out the change from ₹10, ₹20 or ₹50", "Can make a given amount using different combinations of coins and notes", "Can check whether the money offered is enough to buy something"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g2.geo.2d-3d-shapes", "title": "2D and 3D Shapes: Faces, Edges, Lines", "grade": 2, "strand": "geo", "description": "Solid shapes like cubes, cuboids, cylinders and spheres have faces you can touch, edges you can run a finger along, and corners that poke. Flat shapes live on the faces of solids. Learning to count faces, edges and corners — and to tell straight lines from curves — makes us precise about shapes.", "prereqs": ["g1.geo.shapes-around-us"], "outcomes": ["Can name cube, cuboid, cylinder, cone and sphere from real objects", "Can count the faces, edges and corners of a cube or cuboid", "Can predict the flat shape a solid's face will print or trace", "Can tell straight lines from curved lines and draw both"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g2.mea.length-units-intro", "title": "Measuring Length: Non-standard to Standard Units", "grade": 2, "strand": "mea", "description": "We can measure length with handspans, footsteps or pencils — but everyone's hands and feet are different, so the counts don't match. That is why the world agreed on standard units like the centimetre and metre. Measuring means laying units end to end with no gaps and no overlaps, then counting them.", "prereqs": ["g1.mea.compare-lengths"], "outcomes": ["Can measure a length by repeating a unit end to end with no gaps or overlaps", "Can explain why different people get different handspan counts for the same object", "Can say why standard units like centimetre and metre are needed", "Can measure short lengths in centimetres with a ruler"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g2.mea.weight-capacity-intro", "title": "Weight and Capacity: Comparing and Measuring", "grade": 2, "strand": "mea", "description": "Weight tells how heavy something is; capacity tells how much a container can hold. A balance shows which of two things is heavier — the heavier side goes down. To compare containers fairly, we fill them using the same cup and count. Looks can trick us: big things can be light, and tall containers can hold less.", "prereqs": ["g1.mea.compare-lengths"], "outcomes": ["Can compare two objects' weights using hands or a simple balance", "Can read a pan balance: the heavier side goes down", "Can compare two containers' capacities by filling with a common cup and counting", "Can order three objects by weight or three containers by capacity"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g2.mea.time-days-calendar", "title": "Time: Days, Months, Calendar and O'Clock", "grade": 2, "strand": "mea", "description": "The 7 days of the week go round and round like a wheel, and the 12 months fill a year on the calendar. A clock has two hands: the short hand tells the hour, and when the long hand points to 12, it is exactly o'clock. Reading calendars and clocks helps us plan our days.", "prereqs": ["g1.mea.time-day-events"], "outcomes": ["Can say the days of the week in order and name yesterday/tomorrow for any day", "Can name the 12 months in order and find dates on a calendar", "Can read o'clock times on a clock with hands", "Can tell which hand of a clock shows hours and which shows minutes"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g2.alg.patterns-grow", "title": "Growing Patterns in Numbers and Shapes", "grade": 2, "strand": "alg", "description": "Some patterns don't repeat — they GROW. A staircase gains a step each time; the numbers 2, 4, 6, 8 climb by 2 at every jump. To continue a growing pattern you must find its rule: what changes from one step to the next, and by how much?", "prereqs": ["g1.alg.patterns-repeat", "g1.num.add-sub-within-20"], "outcomes": ["Can continue a number pattern that grows by the same amount each time", "Can build and extend growing shape patterns (staircases, triangles of dots)", "Can state the rule of a growing pattern in words ('add 5 each time')", "Can check whether a claimed rule works for EVERY step of a pattern"], "difficulty": 2, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g2.dat.pictographs-intro", "title": "Pictographs: Recording and Reading Data", "grade": 2, "strand": "dat", "description": "A pictograph shows information using little pictures — one picture for each thing counted (or sometimes for two or more). Lining the pictures up in neat rows lets us see at a glance which group has most and how many more. Pictographs turn messy counts into a story our eyes can read.", "prereqs": ["g1.dat.sort-classify", "g1.num.numbers-to-20"], "outcomes": ["Can collect simple data by counting and record it with tally marks or pictures", "Can read how many each row of a pictograph shows", "Can answer most/least and how-many-more questions from a pictograph", "Can use a key where one symbol stands for more than one object"], "difficulty": 1, "est_minutes": 25, "stub": false, "micros": []}, {"id": "g3.num.numbers-to-9999", "title": "4-digit Numbers and Place Value", "grade": 3, "strand": "num", "description": "With four places — thousands, hundreds, tens and ones — we can name every number up to 9999. Each step left multiplies a digit's value by ten, and a zero holds any empty place. Reading, writing, expanding and comparing 4-digit numbers makes big numbers as friendly as small ones.", "prereqs": ["g2.num.numbers-to-999"], "outcomes": ["Can read and write 4-digit numbers from words and figures", "Can give the place value of any digit in a 4-digit number", "Can write a 4-digit number in expanded form (3206 = 3000 + 200 + 6)", "Can compare and order 4-digit numbers", "Can find 1, 10, 100 or 1000 more or less than a given number"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g3.num.add-sub-3digit", "title": "3-digit Addition and Subtraction", "grade": 3, "strand": "num", "description": "Adding and subtracting 3-digit numbers uses the same regrouping ideas as 2-digit work — just with a hundreds column too. Carries can travel from ones to tens to hundreds, and borrowing can even cross a zero. Estimating first tells us roughly what to expect, so wild answers get caught.", "prereqs": ["g2.num.add-sub-2digit", "g2.num.numbers-to-999"], "outcomes": ["Can add two 3-digit numbers with one or more carries", "Can subtract 3-digit numbers with borrowing, including across a zero", "Can estimate a sum or difference to the nearest hundred before computing", "Can check subtraction by adding back", "Can solve story problems needing 3-digit addition or subtraction"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g3.num.mult-tables", "title": "Multiplication Tables and Facts (2–10)", "grade": 3, "strand": "num", "description": "The multiplication tables from 2 to 10 are the fact family of arithmetic — knowing them by heart makes every later calculation faster. But tables are more than a chant: each fact is an array you can picture, facts connect (7 × 6 is 7 × 5 and 7 more), and order never matters. Special rules for 0 and 1 complete the set.", "prereqs": ["g2.num.mult-intro"], "outcomes": ["Can recall multiplication facts for tables 2 to 10", "Can use a known fact to derive a nearby one (7 × 6 = 7 × 5 + 7)", "Can explain why n × 0 = 0 and n × 1 = n", "Can use the turn-around rule: a × b = b × a", "Can find the missing factor in facts like 6 × __ = 42"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g3.num.mult-2digit-by-1digit", "title": "Multiplying 2-digit by 1-digit Numbers", "grade": 3, "strand": "num", "description": "To multiply a number like 47 by 3, we split it by place value: 3 × 40 and 3 × 7, then add the parts. Written short, this becomes the column method with carrying. BOTH parts of the number must be multiplied — that is the heart of the method.", "prereqs": ["g3.num.mult-tables", "g2.num.place-value-2digit"], "outcomes": ["Can multiply a 2-digit number by a 1-digit number using expanded form (area model)", "Can use the column method with carrying", "Can estimate the product first (47 × 3 is about 50 × 3 = 150)", "Can solve story problems involving equal groups of 2-digit amounts"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g3.num.division-intro", "title": "Division: Sharing, Grouping and Inverse of Multiplication", "grade": 3, "strand": "num", "description": "Division answers two kinds of questions: sharing (12 laddoos among 3 children — how many each?) and grouping (12 laddoos, 3 per bag — how many bags?). It is multiplication run backwards: 12 ÷ 3 = 4 because 3 × 4 = 12. Sometimes things don't share out evenly, and what's left over is the remainder.", "prereqs": ["g3.num.mult-tables"], "outcomes": ["Can solve sharing and grouping problems by acting them out or drawing", "Can write and read division sentences (12 ÷ 3 = 4)", "Can use a multiplication fact to solve a division (12 ÷ 3 via 3 × ? = 12)", "Can handle simple leftovers (remainders) in sharing stories"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g3.num.fractions-intro", "title": "Fractions: Half, Quarter, Third", "grade": 3, "strand": "num", "description": "A fraction names a fair share: a half is one of 2 EQUAL parts, a third is one of 3, a quarter is one of 4. The parts must be equal — a big piece and a small piece are not halves! Because quarters are smaller than halves, the more parts we cut, the smaller each part becomes.", "prereqs": ["g3.num.division-intro"], "outcomes": ["Can fold or cut a shape into halves, thirds and quarters — with EQUAL parts", "Can name and write 1/2, 1/3, 1/4 for one part of an equally divided whole", "Can explain that 1/2 of the same whole is bigger than 1/4", "Can find half or a quarter of a small collection (half of 8 mangoes)"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g3.num.money-add-sub", "title": "Money: Making Bills, Adding and Subtracting Amounts", "grade": 3, "strand": "num", "description": "Real shopping needs real arithmetic: adding up a bill with several items, multiplying when we buy more than one of something, and working out change from ₹50 or ₹100. Remember that 100 paise make ₹1, and always check: change must be less than what you handed over!", "prereqs": ["g2.num.money-transactions", "g3.num.add-sub-3digit"], "outcomes": ["Can add amounts of money to make a simple bill", "Can find the change from ₹50 or ₹100", "Can multiply a price by a small quantity within a bill", "Can convert between rupees and paise (₹1 = 100 paise)", "Can judge whether a total or change is reasonable"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g3.geo.lines-shapes", "title": "Lines, Corners and Shape Composition", "grade": 3, "strand": "geo", "description": "Shapes are built from lines and corners: straight lines, curved lines, sides that meet at corners. A shape keeps its name however it is turned — a tilted square is still a square. And shapes combine: two equal triangles can join to make a square, tangram pieces build pictures. Composing and decomposing shapes is geometry's version of adding and subtracting.", "prereqs": ["g2.geo.2d-3d-shapes"], "outcomes": ["Can identify straight and curved lines in drawings and objects, in any direction", "Can count sides and corners of polygons and use them to name shapes", "Can recognise a shape in any orientation", "Can compose new shapes from tangram-style pieces and predict what two shapes will make"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g3.mea.length-std-units", "title": "Length in Centimetres and Metres; Estimation", "grade": 3, "strand": "mea", "description": "Centimetres measure small things (your finger is about 1 cm wide) and metres measure big things (a big step is about 1 m). There are 100 centimetres in 1 metre. Reading a ruler from the 0 mark, choosing the right unit and estimating before measuring make us smart measurers.", "prereqs": ["g2.mea.length-units-intro"], "outcomes": ["Can measure lengths in cm with a ruler, starting from the 0 mark", "Can state that 1 m = 100 cm and pick cm or m sensibly for an object", "Can estimate lengths using body benchmarks before measuring", "Can measure correctly even when the object doesn't start at 0 (broken-ruler problems)"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g3.mea.weight-capacity", "title": "Weight (g, kg) and Capacity (mL, L)", "grade": 3, "strand": "mea", "description": "We weigh things in grams and kilograms (1 kg = 1000 g) and measure liquids in millilitres and litres (1 L = 1000 mL). Choosing the right unit matters: a pencil in grams, a rice sack in kilograms; a spoon of medicine in mL, a bucket in litres. Balances and measuring jars turn 'heavier' and 'holds more' into exact numbers.", "prereqs": ["g2.mea.weight-capacity-intro"], "outcomes": ["Can state 1 kg = 1000 g and 1 L = 1000 mL", "Can choose sensible units (g/kg, mL/L) for everyday objects and containers", "Can read simple weights and volumes from balances and measuring jars", "Can compare and add simple weights and capacities in the same unit"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g3.mea.time-clock", "title": "Reading the Clock and Calendar", "grade": 3, "strand": "mea", "description": "The clock's long hand counts minutes in fives — pointing at 3 means 15 minutes past. The short hour hand creeps between numbers: at half past 4 it sits halfway from 4 to 5, but the hour is still 4. Together with the calendar's dates, days and months, clocks let us plan and keep our promises on time.", "prereqs": ["g2.mea.time-days-calendar"], "outcomes": ["Can read times to the half and quarter hour, and to 5 minutes", "Can explain what each hand shows, including the hour hand between numbers", "Can count minutes in fives around the clock face", "Can find how many days between two dates on a calendar"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g3.alg.patterns-number", "title": "Number Patterns: Skip Counting, Even and Odd", "grade": 3, "strand": "alg", "description": "Numbers make patterns of their own: skip counting by 2s, 5s and 10s from any starting point, and the even-odd rhythm that alternates forever. A number is even if it splits into pairs with none left over — and you can tell just by looking at its ones digit. Spotting these patterns builds the number sense that powers multiplication and algebra.", "prereqs": ["g2.alg.patterns-grow", "g2.num.mult-intro"], "outcomes": ["Can skip count by 2s, 5s and 10s starting from any number", "Can say whether a number is even or odd using the ones digit", "Can explain even numbers as 'splits into pairs with none left over'", "Can describe and extend a number pattern by stating its rule"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g3.dat.tables-bar-charts-intro", "title": "Tables and Simple Bar Charts", "grade": 3, "strand": "dat", "description": "A table lines data up in rows and columns; a bar chart turns those numbers into bars whose heights we can compare at a glance. To read a bar we follow its top across to the scale — and when one step of the scale stands for 2 or more, we must multiply, not just count steps. Charts help us answer questions with evidence.", "prereqs": ["g2.dat.pictographs-intro"], "outcomes": ["Can record counts in a table using tally marks", "Can read values from a simple bar chart using its scale", "Can answer most/least and how-many-more questions from a chart", "Can draw a bar chart from a small table of data"], "difficulty": 2, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g4.num.numbers-to-100000", "title": "5-digit Numbers: Place Value and the Indian System", "grade": 4, "strand": "num", "description": "Numbers up to 1,00,000 open the door to real-world quantities like town populations, distances between cities and prices of scooters. You will read, write, compare and order 5-digit numbers, and use the Indian system of commas (ones, tens, hundreds, thousands, ten thousands). Knowing what each digit is worth is the key skill that all later arithmetic is built on.", "prereqs": ["g3.num.numbers-to-9999"], "outcomes": ["Can read and write 5-digit numbers in figures and words using Indian-system commas", "Can state the place value and face value of any digit in a 5-digit number", "Can compare and order 5-digit numbers by first counting digits, then comparing place by place", "Can expand a number as thousands + hundreds + tens + ones and rebuild it"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g4.num.add-sub-large", "title": "Addition and Subtraction of Larger Numbers", "grade": 4, "strand": "num", "description": "Adding and subtracting 4- and 5-digit numbers lets you handle real quantities — ticket sales, populations, bank balances. The column method works exactly as it did for small numbers; the new challenges are carrying and borrowing across several places, especially across zeros. Estimation first tells you whether your exact answer is sensible.", "prereqs": ["g4.num.numbers-to-100000", "g3.num.add-sub-3digit"], "outcomes": ["Can add two numbers up to 5 digits with regrouping in any column", "Can subtract with borrowing, including across one or more zeros", "Can solve two-step word problems involving addition and subtraction", "Can estimate a sum or difference to check whether an exact answer is reasonable"], "difficulty": 1, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g4.num.mult-multi-digit", "title": "Multi-digit Multiplication", "grade": 4, "strand": "num", "description": "Multiplying 2- and 3-digit numbers lets you scale things up fast: chairs in a hall, sticks of chalk in a delivery, rupees earned per day over a month. The big idea is breaking a number into tens and ones, multiplying each part, and adding the partial products — the written algorithm is just a tidy record of that.", "prereqs": ["g3.num.mult-tables", "g3.num.mult-2digit-by-1digit"], "outcomes": ["Can multiply a 2- or 3-digit number by a 1-digit number with carrying", "Can multiply two 2-digit numbers using partial products or the column method", "Can explain why a zero placeholder appears when multiplying by the tens digit", "Can solve multiplication word problems and check answers by estimating"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g4.num.division-long-intro", "title": "Long Division with 1-digit Divisors and Remainders", "grade": 4, "strand": "num", "description": "Long division shares a big number into equal groups place by place: divide, multiply, subtract, bring down. The remainder tells you what is left over when the sharing cannot be completed — and in real problems, deciding what to do with that remainder is as important as the division itself.", "prereqs": ["g3.num.division-intro", "g3.num.mult-tables"], "outcomes": ["Can divide a 2- or 3-digit number by a 1-digit number using long division", "Can express and check an answer as quotient × divisor + remainder = dividend", "Can explain why a remainder must be smaller than the divisor", "Can interpret the remainder sensibly in word problems (round up, drop, or report it)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g4.num.fractions-equal-parts", "title": "Fractions: Equal Parts, Comparing and Equivalence Intro", "grade": 4, "strand": "num", "description": "A fraction names equal parts of a whole: the bottom number tells how many equal parts the whole is cut into, and the top number tells how many of them we take. You will name fractions from pictures, compare simple fractions of the same whole, and meet the surprising idea that different-looking fractions like 1/2 and 3/6 can name the same amount.", "prereqs": ["g3.num.fractions-intro"], "outcomes": ["Can explain why fraction parts must be equal, and reject unequal-part 'fractions'", "Can name the fraction shown by a shaded region or a shared collection", "Can compare unit fractions of the same whole (1/4 vs 1/6) with a reason", "Can find a simple equivalent fraction using a picture or by doubling both numbers"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g4.geo.circle-intro", "title": "The Circle: Centre and Radius", "grade": 4, "strand": "geo", "description": "A circle is the set of all points at the same distance from one special point, the centre. That fixed distance is the radius, and a line through the centre from edge to edge is the diameter — always twice the radius. This 'same distance all around' idea explains why wheels roll smoothly and why a compass draws a perfect circle.", "prereqs": ["g3.geo.lines-shapes", "g3.mea.length-std-units"], "outcomes": ["Can identify and label the centre, radius and diameter of a circle", "Can explain that all radii of a circle are equal, and use diameter = 2 × radius", "Can draw a circle of a given radius with a compass", "Can explain why wheels are circles using the equal-radius property"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g4.geo.symmetry-reflection", "title": "Symmetry and Reflection", "grade": 4, "strand": "geo", "description": "A shape has line symmetry when one half folds exactly onto the other — the fold line is the line of symmetry, and it acts like a mirror. You will find symmetry lines by folding and with mirrors, count them for common shapes and letters, and draw the mirror image of a simple figure.", "prereqs": ["g3.geo.lines-shapes"], "outcomes": ["Can test a proposed line of symmetry by folding or with a mirror", "Can find all lines of symmetry of squares, rectangles, triangles and letters", "Can draw the reflection of a simple shape across a mirror line", "Can explain why equal halves are not always mirror halves (e.g. a rectangle's diagonal)"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g4.mea.perimeter-intro", "title": "Perimeter as Boundary Length", "grade": 4, "strand": "mea", "description": "Perimeter is the total length of the boundary of a shape — the distance you would walk going once around it. You find it by adding all the side lengths. It answers real questions like how much fencing a field needs or how much lace goes around a tablecloth, and it is measured in units of length (cm, m).", "prereqs": ["g3.mea.length-std-units", "g3.num.add-sub-3digit"], "outcomes": ["Can find the perimeter of any straight-sided shape by adding all its side lengths", "Can find the perimeter of rectangles and squares, using the repeated sides", "Can solve fencing/border word problems, including finding a missing side from the perimeter", "Can explain that shapes with the same area can have different perimeters"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g4.mea.area-intro", "title": "Area by Counting Squares", "grade": 4, "strand": "mea", "description": "Area measures how much surface a shape covers, and we measure it by counting unit squares that tile the shape. Full squares count as 1, two half squares make 1, and rows of squares can be counted quickly with multiplication. Area answers 'how much carpet, paint or land?' — a different question from how long the boundary is.", "prereqs": ["g3.geo.lines-shapes", "g3.num.mult-tables"], "outcomes": ["Can find the area of a shape on squared paper by counting unit squares, combining half squares", "Can use rows × columns to count squares in a rectangle quickly", "Can compare areas of different shapes drawn on the same grid", "Can explain the difference between area (covering) and perimeter (boundary)"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g4.mea.time-duration", "title": "Elapsed Time and the 24-hour Clock", "grade": 4, "strand": "mea", "description": "Elapsed time is how long something lasts — from a movie's start to its end, or a train's departure to its arrival. Because an hour has 60 minutes (not 100), adding and subtracting times needs care at the hour boundary. The 24-hour clock, used in railway timetables, removes the confusion between morning and evening times.", "prereqs": ["g3.mea.time-clock"], "outcomes": ["Can convert between 12-hour (am/pm) and 24-hour clock times", "Can add a duration to a start time, regrouping 60 minutes into 1 hour", "Can find the elapsed time between two clock times, including across noon", "Can read a railway timetable and answer duration questions from it"], "difficulty": 1, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g4.mea.unit-conversions", "title": "Unit Conversions: Length, Weight, Capacity", "grade": 4, "strand": "mea", "description": "Metres and centimetres, kilograms and grams, litres and millilitres — the metric system connects big and small units by factors of 100 and 1000. Converting between them means multiplying when going to smaller units and dividing when going to bigger ones. Mixed measures like 3 m 5 cm must be handled place by place, not glued together.", "prereqs": ["g3.mea.length-std-units", "g3.mea.weight-capacity", "g3.num.mult-tables"], "outcomes": ["Can state the key metric relations: 1 m = 100 cm, 1 km = 1000 m, 1 kg = 1000 g, 1 L = 1000 mL", "Can convert a measure to a smaller unit by multiplying, and to a larger unit by dividing", "Can express mixed measures (3 m 5 cm) as a single unit correctly", "Can choose sensible units and estimate everyday lengths, weights and capacities"], "difficulty": 1, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g4.alg.patterns-rules", "title": "Patterns and Rules", "grade": 4, "strand": "alg", "description": "A pattern is a sequence built by a rule — add the same number, double, or repeat a block of shapes. The mathematician's job is to find the rule, check it against EVERY step given, and then use it to predict what comes next (or far ahead) without drawing everything. This is the first step toward algebra.", "prereqs": ["g3.alg.patterns-number"], "outcomes": ["Can find and state the rule of a number pattern and extend it", "Can check a proposed rule against every given term, not just the first pair", "Can identify the repeating unit of a shape pattern and predict a far-away term (e.g. the 20th shape)", "Can create a pattern from a given rule and describe features of it"], "difficulty": 1, "est_minutes": 30, "stub": false, "micros": []}, {"id": "g4.dat.bar-charts", "title": "Reading and Drawing Bar Charts", "grade": 4, "strand": "dat", "description": "A bar chart shows data as bars whose heights stand for amounts, read off a scaled axis. The crucial skill is using the scale: when one division stands for 5 or 10, you multiply divisions by the scale instead of counting lines. You will read values, compare categories, answer 'how many more' questions and draw your own charts from a table.", "prereqs": ["g3.dat.tables-bar-charts-intro", "g3.num.mult-tables"], "outcomes": ["Can read a value from a bar chart whose scale is 2, 5 or 10 per division", "Can compare two bars and find 'how many more/less' as a difference of values", "Can draw a bar chart from a data table, choosing a sensible scale", "Can answer multi-step questions (totals, differences) from one chart"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g5.num.large-numbers", "title": "Large Numbers: Lakhs, Comparing, Rounding", "grade": 5, "strand": "num", "description": "Beyond ten thousand come lakhs (1,00,000) and ten lakhs — the numbers of city populations, fish-catch tonnages and film box-office collections. You will read and write 6- and 7-digit numbers in the Indian system, compare and order them, and round them to the nearest ten, hundred or thousand to make them easy to talk about.", "prereqs": ["g4.num.numbers-to-100000"], "outcomes": ["Can read and write numbers up to ten lakh using Indian-system commas", "Can compare and order large numbers by digit count, then place-by-place", "Can round a number to the nearest ten, hundred or thousand using the digit to the right", "Can use rounded numbers to estimate sums and to sense-check calculations"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g5.num.mult-div-large", "title": "Multiplication and Division with Larger Numbers", "grade": 5, "strand": "num", "description": "Now the numbers grow: multiplying 3-digit numbers by 2-digit numbers, multiplying by tens and hundreds using zero patterns, and dividing by 2-digit numbers. The methods are the same ones you know — partial products and divide-multiply-subtract-bring-down — applied with more care, and always sanity-checked with estimation.", "prereqs": ["g4.num.mult-multi-digit", "g4.num.division-long-intro"], "outcomes": ["Can multiply by 10, 100 and their multiples using zero patterns correctly", "Can multiply a 3-digit number by a 2-digit number using partial products", "Can divide by a 2-digit divisor, with the remainder smaller than the divisor", "Can estimate products and quotients first, and verify division by multiplying back"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g5.num.factors-multiples", "title": "Factors, Multiples and Prime Numbers Intro", "grade": 5, "strand": "num", "description": "A factor of a number divides it exactly; a multiple is what you get by multiplying it. Factors come in pairs and stop at the number itself, while multiples go on forever. Numbers with exactly two factors — 1 and themselves — are the primes, the building blocks of all whole numbers.", "prereqs": ["g3.num.mult-tables", "g3.num.division-intro"], "outcomes": ["Can list all factors of a number systematically using factor pairs", "Can list multiples of a number and decide whether one number is a multiple of another", "Can explain the difference between a factor and a multiple of a number", "Can identify prime and composite numbers up to 100 by testing small divisors"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g5.num.fractions-equivalent-compare", "title": "Equivalent Fractions and Comparison", "grade": 5, "strand": "num", "description": "Different fractions can name the same amount: 1/2, 2/4 and 3/6 all sit at the same point. You make equivalent fractions by multiplying or dividing BOTH the numerator and denominator by the same number. With equivalence in hand you can compare any two fractions — by common denominators, by same numerators, or by clever benchmarks like 'how far from one whole?'.", "prereqs": ["g4.num.fractions-equal-parts"], "outcomes": ["Can generate equivalent fractions by multiplying or dividing both terms by the same number", "Can reduce a fraction to its simplest form", "Can compare fractions with the same denominator, the same numerator, or neither", "Can use benchmarks (1/2, 1 whole, distance from 1) to compare fractions mentally"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g5.num.fractions-add-sub", "title": "Adding and Subtracting Fractions (Like and Related Denominators)", "grade": 5, "strand": "num", "description": "Fractions can only be added or subtracted when the pieces are the same size — the same denominator. With like denominators you simply add or subtract the counts of pieces. When one denominator is a multiple of the other (halves and quarters, thirds and sixths), you first re-cut one fraction into the finer pieces, then combine. Wholes join in by renaming 1 as 4/4, 8/8 and so on.", "prereqs": ["g5.num.fractions-equivalent-compare", "g4.num.fractions-equal-parts"], "outcomes": ["Can add and subtract fractions with the same denominator, keeping the denominator fixed", "Can add and subtract fractions where one denominator is a multiple of the other", "Can rename a whole as an equivalent fraction to subtract from it", "Can solve one-step fraction word problems about sharing food, time and lengths"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g5.num.decimals-intro", "title": "Decimals: Tenths and Hundredths", "grade": 5, "strand": "num", "description": "Decimals extend place value to the right of the ones: tenths and hundredths, separated by the decimal point. 0.7 means 7 tenths (7/10), and 0.07 means 7 hundredths — ten times smaller. Decimals run our money (₹ and paise), our measurements (metres and centimetres) and every price tag, so reading them correctly matters every day.", "prereqs": ["g4.num.fractions-equal-parts", "g4.num.numbers-to-100000"], "outcomes": ["Can read and write tenths and hundredths as fractions and as decimals", "Can place decimals like 0.3 and 0.45 on a number line between whole numbers", "Can compare two decimals by comparing place by place, not by digit count", "Can connect decimals to money (₹1 = 100 paise) and measures (1 m = 100 cm)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g5.num.decimals-add-sub", "title": "Adding and Subtracting Decimals", "grade": 5, "strand": "num", "description": "Adding and subtracting decimals works exactly like whole numbers — as long as you line up the decimal points so tenths sit under tenths and hundredths under hundredths. Appending zeros (4.5 = 4.50) makes ragged numbers tidy. These are the calculations of shopkeepers and shoppers: totals, change and measurements every single day.", "prereqs": ["g5.num.decimals-intro", "g4.num.add-sub-large"], "outcomes": ["Can add and subtract decimals by aligning the decimal points", "Can pad with trailing zeros to equalise decimal places before computing", "Can regroup across the decimal point (10 tenths = 1 one)", "Can solve money and measurement problems, including making change"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g5.geo.angles-intro", "title": "Angles: Right Angles and Degree Intuition", "grade": 5, "strand": "geo", "description": "An angle measures a TURN — how far one arm swings away from the other. A right angle (a square corner) is 90 degrees, a straight angle is 180, and a full turn is 360. Angle size depends only on the amount of turn, not on how long the arms are drawn or which way the corner faces.", "prereqs": ["g3.geo.lines-shapes"], "outcomes": ["Can identify right, acute and obtuse angles in shapes and surroundings", "Can state the degree landmarks: 90 (right), 180 (straight), 360 (full turn)", "Can compare two angles by amount of turn, ignoring arm length and orientation", "Can estimate everyday angles (clock hands, open doors, scissors) against the 90-degree benchmark"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g5.geo.nets-3d", "title": "3D Shapes, Boxes and Nets", "grade": 5, "strand": "geo", "description": "A net is a flat pattern that folds up into a solid — unfold a toothpaste box and you are looking at its net. You will count faces, edges and corners of cubes and cuboids, decide which arrangements of squares fold into a cube and which do not, and sketch boxes on flat paper. This is the skill of packaging designers everywhere.", "prereqs": ["g2.geo.2d-3d-shapes", "g3.geo.lines-shapes"], "outcomes": ["Can count faces, edges and vertices of cubes and cuboids", "Can decide by mental folding whether a given arrangement of squares is a net of a cube", "Can match a box to its net and mark which faces end up opposite each other", "Can draw a simple net for an open or closed box"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g5.geo.patterns-symmetry-turns", "title": "Symmetry, Turns and Tiling Patterns", "grade": 5, "strand": "geo", "description": "Some shapes look exactly the same after a quarter turn (90°) or a half turn (180°) — that is turning (rotational) symmetry, a cousin of mirror symmetry but not the same thing. Turns also build patterns: many rangoli, tile and border designs repeat a single motif by rotating it again and again. You will predict what a shape looks like after a turn and continue turn-based patterns.", "prereqs": ["g4.geo.symmetry-reflection", "g4.alg.patterns-rules", "g5.geo.angles-intro"], "outcomes": ["Can state that a quarter turn is 90°, a half turn 180° and a full turn 360°", "Can predict what a shape or letter looks like after a quarter or half turn", "Can test whether a figure looks the same after a given turn, and distinguish this from mirror symmetry", "Can continue and create tiling/border patterns built from repeated turns of one motif"], "difficulty": 1, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g5.mea.area-perimeter-rect", "title": "Area and Perimeter of Rectangles (Formulas)", "grade": 5, "strand": "mea", "description": "Counting squares one by one is slow — for rectangles, multiplication does it instantly: area = length × width, because the squares sit in equal rows. Perimeter has its own shortcut: 2 × (length + width). The two formulas answer two different questions (covering vs surrounding), use different units (square cm vs cm), and mixing them up is the classic trap.", "prereqs": ["g4.mea.area-intro", "g4.mea.perimeter-intro", "g4.num.mult-multi-digit"], "outcomes": ["Can compute the area of a rectangle as length × width and justify it with rows of squares", "Can compute the perimeter of a rectangle as 2 × (length + width)", "Can attach the correct units: square units for area, length units for perimeter", "Can find a missing side given the area or perimeter, and compare rectangles with equal perimeter"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g5.mea.volume-intuition", "title": "Volume Intuition with Unit Cubes", "grade": 5, "strand": "mea", "description": "Volume measures how much space something fills, and we measure it by counting unit cubes — including the ones hidden inside and underneath. A box packs cubes in layers: cubes per layer × number of layers. Rearranging the same cubes into a tower or a slab changes the shape but never the volume.", "prereqs": ["g4.mea.area-intro", "g5.geo.nets-3d", "g3.num.mult-tables"], "outcomes": ["Can find the volume of a cube-built solid by counting unit cubes, including hidden ones", "Can use layers to count: cubes in one layer × number of layers", "Can explain that rearranging cubes changes shape but not volume", "Can compare volumes of two cube buildings and order containers by how much they hold"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g5.dat.data-interpretation", "title": "Interpreting Tables, Bar Graphs and Simple Pie Charts", "grade": 5, "strand": "dat", "description": "Data answers questions — if you read it correctly. You will pull values out of tables, read scaled bar graphs precisely (including part-divisions), and interpret simple pie charts where a slice is a fraction of the total. The golden rules: check the scale, and remember a pie slice is a fraction — its actual count depends on the total.", "prereqs": ["g4.dat.bar-charts", "g4.num.fractions-equal-parts"], "outcomes": ["Can extract and compare values from a data table, including finding least and greatest", "Can read bar graphs with scaled axes, including bars ending between gridlines", "Can interpret a simple pie chart by applying its fractions (half, quarter) to the stated total", "Can answer multi-step questions combining two or more readings from one display"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g6.num.knowing-numbers", "title": "Knowing Our Numbers: Large Numbers and Estimation", "grade": 6, "strand": "num", "description": "You will read, write, compare and order large numbers in both the Indian (lakh, crore) and international (million, billion) systems, and use rounding to estimate sums, differences and products. Estimation is the everyday superpower of mathematics: it lets you sanity-check bills, budgets and news headlines in seconds.", "prereqs": ["g5.num.large-numbers"], "outcomes": ["Can read and write numbers up to crores using both Indian and international place-value systems, with correct comma placement", "Can compare and order large numbers by aligning place values, not just by looking at leading digits", "Can round a number to the nearest ten, hundred, thousand or lakh", "Can estimate the result of an addition, subtraction or multiplication and judge whether an exact answer is reasonable"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g6.num.whole-numbers", "title": "Whole Numbers and Their Properties", "grade": 6, "strand": "num", "description": "Whole numbers are the counting numbers together with zero. You will explore their behaviour on the number line and the properties of addition and multiplication — commutativity, associativity, distributivity and the special roles of 0 and 1 — and use these properties to compute cleverly instead of laboriously.", "prereqs": ["g6.num.knowing-numbers", "g5.num.mult-div-large"], "outcomes": ["Can identify predecessors and successors and locate whole numbers on a number line", "Can state which operations on whole numbers are commutative and associative, with counterexamples for subtraction and division", "Can use distributivity and regrouping to simplify calculations such as 8 × 293 × 125 mentally", "Can explain the roles of 0 and 1 as identities and why division by zero is undefined"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g6.num.playing-with-numbers", "title": "Factors, Multiples, Divisibility, HCF and LCM", "grade": 6, "strand": "num", "description": "Numbers have hidden structure: factors, multiples, primes and composites. You will learn divisibility tests, prime factorisation, and how to find the HCF (highest common factor) and LCM (lowest common multiple) of numbers — tools you will use constantly with fractions, ratios and repeating events.", "prereqs": ["g5.num.factors-multiples", "g3.num.division-intro"], "outcomes": ["Can list factors and multiples of a number and classify numbers as prime or composite", "Can apply divisibility tests for 2, 3, 4, 5, 6, 8, 9, 10 and 11", "Can find HCF and LCM using prime factorisation and choose which one a word problem needs", "Can verify and use the relation HCF × LCM = product of the two numbers"], "difficulty": 2, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g6.num.integers-intro", "title": "Integers: Negative Numbers, Ordering, Addition and Subtraction", "grade": 6, "strand": "num", "description": "Integers extend the number line to the left of zero, letting us describe temperatures below freezing, depths below sea level and money owed. You will order integers, and add and subtract them using the number line and zero-pair models — the foundation for all of algebra.", "prereqs": ["g6.num.whole-numbers"], "outcomes": ["Can represent real situations (temperature, altitude, credit/debit) with positive and negative integers", "Can place integers on a number line and compare/order them correctly", "Can add integers with like and unlike signs using number-line moves or zero pairs", "Can subtract integers, including subtracting a negative, and explain why 5 − (−2) = 7"], "difficulty": 2, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g6.num.fractions-ops", "title": "Fractions: Proper, Improper, Mixed; Addition and Subtraction", "grade": 6, "strand": "num", "description": "You will work confidently with proper fractions, improper fractions and mixed numbers, convert between forms, and add and subtract fractions with unlike denominators using equivalent fractions and the LCM. This is where fraction arithmetic becomes a reliable tool instead of a guessing game.", "prereqs": ["g5.num.fractions-add-sub", "g5.num.fractions-equivalent-compare", "g6.num.playing-with-numbers"], "outcomes": ["Can convert between improper fractions and mixed numbers in both directions", "Can compare fractions by making denominators (or numerators) equal", "Can add and subtract fractions with unlike denominators using the LCM as common denominator", "Can solve word problems involving addition and subtraction of fractions and judge whether the answer is reasonable"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": []}, {"id": "g6.num.decimals-ops", "title": "Decimals: Comparing, Adding, Subtracting; Units", "grade": 6, "strand": "num", "description": "Decimals are fractions with denominators 10, 100, 1000 written in place-value form. You will compare decimals correctly, add and subtract them by aligning the decimal point, and use them with money and metric units — where decimals live in real life.", "prereqs": ["g5.num.decimals-intro", "g5.num.decimals-add-sub"], "outcomes": ["Can read and write decimals up to thousandths and connect them to fractions", "Can compare and order decimals by place value, including cases like 0.5 vs 0.45", "Can add and subtract decimals by aligning decimal points, padding with zeros where needed", "Can convert between units using decimals (e.g. 145 cm = 1.45 m, 75 paise = ₹0.75)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g6.num.ratio-proportion", "title": "Ratio, Proportion and the Unitary Method", "grade": 6, "strand": "num", "description": "A ratio compares quantities by division rather than subtraction, and a proportion says two ratios are equal. With the unitary method — find the value of ONE, then scale — you can solve price, speed and recipe problems. This multiplicative way of thinking underpins percentages, similar triangles and trigonometry later.", "prereqs": ["g5.num.fractions-equivalent-compare", "g5.num.mult-div-large"], "outcomes": ["Can express a comparison as a ratio in simplest form, attending to order and same units", "Can test whether four numbers are in proportion (a:b = c:d)", "Can use the unitary method: find the value of one unit, then find the value of many", "Can solve real problems on prices, speeds and mixtures using ratio reasoning"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g6.alg.intro-algebra", "title": "Introduction to Algebra: Variables and Expressions", "grade": 6, "strand": "alg", "description": "Algebra begins when a letter stands for a number that can vary. You will write rules for patterns (like the perimeter of a square, 4s), build expressions from operations, and evaluate them for given values. Learning to treat a letter as a NUMBER — not an object or a label — is the single most important idea of this chapter.", "prereqs": ["g4.alg.patterns-rules", "g6.num.whole-numbers"], "outcomes": ["Can use a variable to state a general rule for a pattern (e.g. matchstick patterns, perimeter formulas)", "Can translate word phrases into algebraic expressions and back", "Can evaluate an expression like 2n + 3 for a given value of n", "Can explain that a variable stands for a number that can take many values"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g6.geo.basic-ideas", "title": "Basic Geometrical Ideas: Points, Lines, Curves, Polygons, Circles", "grade": 6, "strand": "geo", "description": "Geometry's vocabulary starts here: points, line segments, rays and lines; open and closed curves; polygons with their sides, vertices and diagonals; and the circle with its centre, radius, diameter and chords. Precise language now makes every later theorem readable.", "prereqs": ["g3.geo.lines-shapes", "g4.geo.circle-intro"], "outcomes": ["Can distinguish a line, a line segment and a ray, and use correct notation for each", "Can identify open/closed curves, and the interior, boundary and exterior of a closed curve", "Can name the parts of a polygon (sides, vertices, adjacent sides, diagonals)", "Can identify centre, radius, diameter, chord, arc and sector of a circle and relate diameter to radius"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g6.geo.elementary-shapes", "title": "Understanding Elementary Shapes: Angles, Triangles, Quadrilaterals, Solids", "grade": 6, "strand": "geo", "description": "You will measure and classify angles (acute, right, obtuse, straight, reflex), classify triangles by sides and angles, meet the family of quadrilaterals, and recognise common solids with their faces, edges and vertices. Classifying shapes trains you to reason from properties rather than appearances.", "prereqs": ["g6.geo.basic-ideas", "g5.geo.angles-intro"], "outcomes": ["Can classify angles as acute, right, obtuse, straight or reflex, and estimate angle sizes", "Can classify triangles by sides (scalene, isosceles, equilateral) and by angles (acute, right, obtuse)", "Can name quadrilaterals and state their defining properties, including how the special quadrilaterals nest (every square is a rectangle)", "Can identify faces, edges and vertices of cubes, cuboids, cylinders, cones, spheres, prisms and pyramids"], "difficulty": 2, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g6.geo.symmetry", "title": "Symmetry: Lines of Symmetry", "grade": 6, "strand": "geo", "description": "A figure has line symmetry when one half folds exactly onto the other. You will find all lines of symmetry of common shapes and letters, and complete half-drawn symmetric figures. Symmetry sharpens visual reasoning and reappears in reflections, transformations and even algebraic graphs.", "prereqs": ["g4.geo.symmetry-reflection"], "outcomes": ["Can test a proposed line of symmetry by (mentally or physically) folding", "Can find ALL lines of symmetry of standard shapes: square (4), rectangle (2), equilateral triangle (3), circle (infinitely many)", "Can identify shapes with no line of symmetry (e.g. scalene triangle, parallelogram)", "Can complete the other half of a figure given the mirror line"], "difficulty": 2, "est_minutes": 35, "stub": false, "micros": []}, {"id": "g6.geo.constructions-intro", "title": "Constructions with Ruler and Compass", "grade": 6, "strand": "geo", "description": "Using only an unmarked straightedge and a compass, you will construct circles, copy segments, draw perpendiculars and perpendicular bisectors, and build angles of 60°, 30°, 90° and 120°. Constructions teach WHY figures have their properties — every arc is a statement about equal distances.", "prereqs": ["g6.geo.basic-ideas", "g4.geo.circle-intro"], "outcomes": ["Can draw a circle of given radius and copy a line segment with compass and ruler", "Can construct the perpendicular bisector of a segment and a perpendicular through a point", "Can construct 60° and related angles (120°, 30°, 90°) and bisect a given angle", "Can explain why a construction works in terms of equal radii (equal distances)"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g6.mea.mensuration-perimeter-area", "title": "Mensuration: Perimeter and Area of Squares and Rectangles", "grade": 6, "strand": "mea", "description": "Perimeter measures the boundary of a figure; area measures the surface it covers. You will use the formulas for squares and rectangles, work with the right units (cm vs cm²), and discover that figures with the same perimeter can enclose very different areas.", "prereqs": ["g5.mea.area-perimeter-rect"], "outcomes": ["Can compute perimeters of rectangles, squares and figures made of straight segments", "Can compute areas of rectangles and squares, and of shapes decomposable into rectangles", "Can attach correct units: linear units for perimeter, square units for area", "Can explain with examples that equal perimeters do not force equal areas (and vice versa)"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g6.dat.data-handling", "title": "Data Handling: Tally Marks, Pictographs, Bar Graphs", "grade": 6, "strand": "dat", "description": "Data becomes useful when organised: you will record data with tally marks, and read and draw pictographs and bar graphs — including ones where a symbol or one unit of height stands for many items. Reading scales correctly is the key skill; it protects you from misleading graphs forever after.", "prereqs": ["g4.dat.bar-charts"], "outcomes": ["Can record raw data in a frequency table using tally marks (bundles of five)", "Can read and draw a pictograph where one symbol represents multiple units, including half symbols", "Can read and draw a bar graph, choosing and using a sensible scale", "Can answer comparison questions ('how many more…?') from a graph, applying the scale correctly"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g7.num.integers-ops", "title": "Integers: Multiplication, Division and Properties", "grade": 7, "strand": "num", "description": "Building on integer addition and subtraction, you will multiply and divide integers, master the sign rules (and why they work), and use properties like distributivity with negative numbers. These rules power all of algebra — every bracket you expand later depends on them.", "prereqs": ["g6.num.integers-intro", "g3.num.mult-tables"], "outcomes": ["Can multiply integers with any combination of signs and justify the sign of the product", "Can divide integers and connect division to multiplication facts", "Can apply commutativity, associativity and distributivity with negative numbers", "Can solve multi-step problems mixing all four operations with integers"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g7.num.fractions-decimals-ops", "title": "Fractions and Decimals: Multiplication and Division", "grade": 7, "strand": "num", "description": "You will multiply and divide fractions and decimals, understand 'of' as multiplication, and see why dividing by a fraction means multiplying by its reciprocal. Along the way you will confront a big surprise: multiplying can make numbers smaller, and dividing can make them bigger.", "prereqs": ["g6.num.fractions-ops", "g6.num.decimals-ops"], "outcomes": ["Can multiply fractions (including mixed numbers) and interpret 'of' as multiplication", "Can divide by a fraction using the reciprocal, and explain why the method works", "Can multiply and divide decimals, placing the decimal point by counting decimal places", "Can predict whether a product/quotient will be bigger or smaller than the starting number"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": []}, {"id": "g7.num.rational-numbers-intro", "title": "Rational Numbers: Representation and Comparison", "grade": 7, "strand": "num", "description": "Rational numbers are all numbers expressible as p/q with integers p, q and q ≠ 0 — uniting integers, fractions and their negatives into one family. You will write rationals in standard form, place them on the number line, compare them, and find rationals between any two given ones.", "prereqs": ["g6.num.integers-intro", "g6.num.fractions-ops"], "outcomes": ["Can write a rational number in standard form (positive denominator, lowest terms)", "Can place positive and negative rationals on the number line", "Can compare and order rational numbers, including negatives", "Can find rational numbers between two given rational numbers"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g7.num.comparing-quantities", "title": "Comparing Quantities: Percentage, Profit and Loss, Simple Interest", "grade": 7, "strand": "num", "description": "Percentages turn every comparison into 'per hundred', making unlike things comparable. You will convert between fractions, decimals and percents, compute percentage increase/decrease, profit and loss on cost price, and simple interest. These are the most-used school mathematics in adult life.", "prereqs": ["g6.num.ratio-proportion", "g6.num.decimals-ops"], "outcomes": ["Can convert fluently between fractions, decimals and percentages", "Can find a percentage of a quantity and express one quantity as a percentage of another", "Can compute profit/loss and profit/loss percent on the cost price", "Can compute simple interest with SI = P × R × T / 100 and find the amount"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": []}, {"id": "g7.num.exponents-intro", "title": "Exponents and Powers: Laws and Standard Form", "grade": 7, "strand": "num", "description": "Exponents compress repeated multiplication: 10⁵ instead of 10×10×10×10×10. You will evaluate powers, use the laws of exponents (product, quotient, power of a power), and write large numbers in standard form. Exponents are the language of both astronomy and algebra.", "prereqs": ["g6.num.whole-numbers", "g7.num.integers-ops"], "outcomes": ["Can evaluate powers with whole-number exponents, including powers of negative bases", "Can apply a^m × a^n = a^(m+n), a^m ÷ a^n = a^(m−n) and (a^m)^n = a^(mn) with justification", "Can use a⁰ = 1 (a ≠ 0) and explain it via the quotient pattern", "Can express large numbers in standard form k × 10^n with 1 ≤ k < 10"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g7.alg.simple-equations", "title": "Simple Equations: Solving One-variable Linear Equations", "grade": 7, "strand": "alg", "description": "An equation is a balance: whatever you do to one side you must do to the other. You will solve equations like 5x − 3 = 12 by systematic inverse operations (or transposition done with understanding), check solutions by substitution, and translate word problems into equations.", "prereqs": ["g6.alg.intro-algebra", "g6.num.integers-intro"], "outcomes": ["Can maintain balance: perform the same operation on both sides of an equation", "Can solve one- and two-step linear equations in one variable, including with integer solutions", "Can verify a solution by substituting it back into the original equation", "Can set up and solve an equation from a word problem"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g7.alg.expressions", "title": "Algebraic Expressions: Terms, Like Terms, Evaluation", "grade": 7, "strand": "alg", "description": "You will take expressions apart into terms, factors and coefficients, combine like terms, add and subtract whole expressions, and evaluate them for given values — including negative ones. Fluency here is what makes equation-solving and identities feel easy next year.", "prereqs": ["g6.alg.intro-algebra", "g7.num.integers-ops"], "outcomes": ["Can identify terms, factors, coefficients, and classify monomials/binomials/trinomials", "Can identify like terms and combine them correctly", "Can add and subtract algebraic expressions, distributing the minus sign over every term", "Can evaluate expressions at given values, including negative values"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g7.geo.lines-angles", "title": "Lines and Angles: Angle Pairs, Parallel Lines and Transversals", "grade": 7, "strand": "geo", "description": "You will work with complementary, supplementary, adjacent and vertically opposite angles, then study what happens when a transversal cuts parallel lines: corresponding and alternate angles are equal, and co-interior angles add to 180°. These angle facts are the raw material of all later geometric proof.", "prereqs": ["g6.geo.elementary-shapes"], "outcomes": ["Can find complements (to 90°) and supplements (to 180°) of given angles", "Can identify and use vertically opposite angles and linear pairs", "Can name corresponding, alternate and co-interior angle pairs at a transversal", "Can compute unknown angles when a transversal cuts parallel lines, justifying each step"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g7.geo.triangle-properties", "title": "The Triangle and Its Properties: Angle Sum, Exterior Angle, Pythagoras Intro", "grade": 7, "strand": "geo", "description": "Every triangle hides three strong laws: its angles sum to 180°, an exterior angle equals the sum of the two remote interior angles, and any two sides together exceed the third. For right triangles you will meet the Pythagoras property relating the squares on the sides.", "prereqs": ["g7.geo.lines-angles"], "outcomes": ["Can use the angle-sum property (180°) to find unknown angles", "Can apply the exterior-angle property: exterior = sum of the two remote interior angles", "Can test whether three lengths can form a triangle (triangle inequality)", "Can use the Pythagoras property to check for right angles and find a missing side in simple cases"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g7.geo.congruence", "title": "Congruence of Triangles: SSS, SAS, ASA, RHS", "grade": 7, "strand": "geo", "description": "Two figures are congruent when one fits exactly on the other. For triangles you don't need to check all six parts: the criteria SSS, SAS, ASA and RHS each guarantee congruence from just three well-chosen parts. Congruence is your first taste of deductive proof.", "prereqs": ["g7.geo.triangle-properties"], "outcomes": ["Can state what congruence means and write correspondences (ΔABC ≅ ΔPQR) in the right order", "Can select and apply the appropriate criterion: SSS, SAS, ASA or RHS", "Can explain why AAA and SSA are NOT valid congruence criteria", "Can extract equal corresponding parts (CPCT) from a stated congruence"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g7.geo.symmetry-rotational", "title": "Symmetry: Line and Rotational", "grade": 7, "strand": "geo", "description": "Beyond mirror lines, shapes can also match themselves under turning: a shape has rotational symmetry of order n if it looks unchanged n times during a full 360° turn. You will find orders and angles of rotation, and discover that line symmetry and rotational symmetry are independent properties.", "prereqs": ["g6.geo.symmetry"], "outcomes": ["Can find the order of rotational symmetry of a figure and its angle of rotation (360°/order)", "Can locate the centre of rotation of a symmetric figure", "Can give examples of shapes with line symmetry only, rotational only, both, and neither", "Can explain why every figure trivially matches itself after a full 360° turn (order at least 1)"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g7.geo.visualising-solids", "title": "Visualising Solid Shapes: Nets, Sketches, Cross-sections", "grade": 7, "strand": "geo", "description": "Solids live in 3D but we draw them in 2D. You will match solids with their nets, draw oblique and isometric sketches, imagine cross-sections made by cuts, and read views (top, front, side) and shadows. Strong 3D visualisation pays off in geometry, science diagrams and engineering drawing.", "prereqs": ["g5.geo.nets-3d", "g6.geo.elementary-shapes"], "outcomes": ["Can count and name faces, edges and vertices of common solids", "Can decide whether a given net folds into a given solid (cube, cuboid, cylinder, cone)", "Can describe the cross-section produced by a horizontal or vertical cut of a solid", "Can interpret and draw top, front and side views of simple solid arrangements"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g7.geo.practical-geometry", "title": "Practical Geometry: Parallel Lines and Triangle Constructions", "grade": 7, "strand": "geo", "description": "With ruler and compass you will construct a line parallel to a given line through a point, and triangles from given data: three sides (SSS), two sides and the included angle (SAS), two angles and a side (ASA), and right triangles (RHS). Each construction succeeds exactly when the corresponding congruence criterion holds — construction and congruence are two sides of the same coin.", "prereqs": ["g6.geo.constructions-intro", "g7.geo.lines-angles", "g7.geo.congruence"], "outcomes": ["Can construct a line parallel to a given line through an external point using equal alternate/corresponding angles", "Can construct triangles from SSS, SAS, ASA and RHS data", "Can recognise data sets that give no triangle (violating the triangle inequality) or more than one triangle", "Can connect each construction to the congruence criterion that guarantees uniqueness"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g7.mea.perimeter-area", "title": "Perimeter and Area: Triangles, Parallelograms, Circles", "grade": 7, "strand": "mea", "description": "You will extend area from rectangles to parallelograms (base × height) and triangles (half of that), and meet the circle's two famous formulas: circumference 2πr and area πr². Choosing the RIGHT base–height pair, and the right formula, is the heart of this chapter.", "prereqs": ["g6.mea.mensuration-perimeter-area", "g7.num.fractions-decimals-ops"], "outcomes": ["Can compute areas of parallelograms and triangles using base and the PERPENDICULAR height", "Can compute circumference and area of circles, using π ≈ 22/7 or 3.14", "Can solve problems with paths, borders and combined figures", "Can convert between units of area (cm², m²) where needed"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g7.dat.data-handling-averages", "title": "Data Handling: Mean, Median, Mode, Range and Chance", "grade": 7, "strand": "dat", "description": "One number can represent a whole data set: the mean (fair share), median (middle of the sorted list) and mode (most frequent value) — each useful in different situations, with range measuring spread. You will also take your first formal steps into probability as a number between 0 and 1.", "prereqs": ["g6.dat.data-handling", "g6.num.decimals-ops"], "outcomes": ["Can compute the mean and explain it as equal sharing / balance point", "Can find the median (after sorting!) and the mode of a data set", "Can choose which average best represents a data set and critique a poor choice", "Can assign simple probabilities as favourable outcomes over total equally likely outcomes"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g8.num.rational-numbers", "title": "Rational Numbers: Properties and Density", "grade": 8, "strand": "num", "description": "You will study rational numbers as a system: closure, commutativity and associativity, the roles of 0 and 1, negatives (additive inverses) and reciprocals (multiplicative inverses), and distributivity as a computation shortcut. The headline property is density — between any two rationals lie infinitely many more.", "prereqs": ["g7.num.rational-numbers-intro", "g7.num.fractions-decimals-ops"], "outcomes": ["Can state and use the properties of operations on rational numbers, with counterexamples for subtraction/division", "Can find additive and multiplicative inverses and keep the two ideas apart", "Can use distributivity to simplify computations like a×b + a×c", "Can find (infinitely many) rational numbers between two given rationals"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g8.num.squares-roots", "title": "Squares and Square Roots", "grade": 8, "strand": "num", "description": "Perfect squares are numbers like 1, 4, 9, 16 — areas of whole-number squares. You will spot their patterns (unit digits, odd-number sums), find square roots by prime factorisation and by long division, and estimate roots of non-perfect squares. Square roots return in Pythagoras, quadratics and beyond.", "prereqs": ["g7.num.exponents-intro", "g6.num.playing-with-numbers"], "outcomes": ["Can compute squares efficiently and recognise perfect squares up to at least 400", "Can use unit-digit and other patterns to rule out non-squares (no perfect square ends in 2, 3, 7 or 8)", "Can find square roots by prime factorisation and by the long-division method", "Can estimate the square root of a non-perfect square between consecutive integers"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g8.num.cubes-roots", "title": "Cubes and Cube Roots", "grade": 8, "strand": "num", "description": "Cubing a number multiplies it by itself three times — the volume of a cube of that side. You will recognise perfect cubes, use prime factorisation (triples of factors) to find cube roots, and exploit unit-digit patterns for quick mental roots. Unlike squares, cubes of negatives stay negative.", "prereqs": ["g8.num.squares-roots"], "outcomes": ["Can compute cubes and recognise perfect cubes up to 1000 (and 12³ = 1728)", "Can find cube roots by grouping prime factors into triples", "Can use unit-digit patterns to find cube roots of perfect cubes mentally", "Can explain why cubes of negative numbers are negative, unlike squares"], "difficulty": 3, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g8.num.comparing-quantities", "title": "Comparing Quantities: Discounts, Compound Interest", "grade": 8, "strand": "num", "description": "Real prices move in chains: marked price → discount → sales tax/GST → final bill, and savings grow by compound interest, where each year's interest itself earns interest. You will compute successive percentage changes correctly by multiplying growth factors — the single most useful trick in consumer maths.", "prereqs": ["g7.num.comparing-quantities"], "outcomes": ["Can compute discount, sale price, and tax/GST on a purchase", "Can handle successive percentage changes by multiplying factors (×0.9, ×1.18, …)", "Can compute compound interest annually (and half-yearly) using A = P(1 + r/100)ⁿ", "Can explain why compound interest exceeds simple interest after the first period"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": []}, {"id": "g8.num.exponents-powers", "title": "Exponents and Powers: Negative Exponents, Scientific Notation", "grade": 8, "strand": "num", "description": "Negative exponents extend the power ladder below 1: 10⁻³ means 1/10³, letting scientific notation describe the very small (a bacterium's width) as easily as the very large. You will apply all the exponent laws with integer exponents and convert numbers to and from standard form in both directions.", "prereqs": ["g7.num.exponents-intro", "g7.num.rational-numbers-intro"], "outcomes": ["Can evaluate powers with negative integer exponents via a⁻ⁿ = 1/aⁿ", "Can apply the laws of exponents across integer exponents, including a⁰ = 1", "Can write very small numbers in standard form k × 10⁻ⁿ and convert back", "Can compare magnitudes expressed in scientific notation"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g8.num.direct-inverse-proportion", "title": "Direct and Inverse Proportion", "grade": 8, "strand": "num", "description": "Two quantities are in direct proportion when their RATIO stays constant (double one, double the other) and in inverse proportion when their PRODUCT stays constant (double one, halve the other). The crucial skill is deciding which model — if either — fits a situation before computing.", "prereqs": ["g6.num.ratio-proportion", "g7.num.fractions-decimals-ops"], "outcomes": ["Can test whether tabled data shows direct proportion (y/x constant) or inverse proportion (xy constant)", "Can solve direct-proportion problems via the constant ratio or unitary method", "Can solve inverse-proportion problems (workers–days, speed–time) via the constant product", "Can identify situations that are NEITHER kind of proportion (e.g. age vs height)"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g8.num.playing-numbers", "title": "Playing with Numbers: General Form and Divisibility", "grade": 8, "strand": "num", "description": "Writing a two-digit number as 10a + b turns number tricks into algebra: you can PROVE why ab + ba is always divisible by 11, justify the divisibility tests for 3 and 9, and crack letter-for-digit puzzles. This chapter is a first taste of proof through generalisation.", "prereqs": ["g6.num.playing-with-numbers", "g7.alg.expressions"], "outcomes": ["Can express 2- and 3-digit numbers in general form (10a + b, 100a + 10b + c)", "Can prove simple facts like 11 | (ab + ba) and 9 | (abc − cba variants) using the general form", "Can justify the divisibility tests for 2, 3, 5, 9 and 10 from place value", "Can solve letter-digit (cryptarithm) puzzles using digit constraints"], "difficulty": 3, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g8.alg.linear-equations-1var", "title": "Linear Equations in One Variable: Variables on Both Sides", "grade": 8, "strand": "alg", "description": "Equations now carry the variable on BOTH sides (2x + 5 = x + 9), and may involve fractions or expressions that need simplifying first. You will reduce them systematically to x = value, and use them to crack age, number, perimeter and money problems.", "prereqs": ["g7.alg.simple-equations", "g8.num.rational-numbers"], "outcomes": ["Can solve linear equations with variables on both sides", "Can clear fractions by multiplying EVERY term by the common denominator", "Can reduce word problems (ages, numbers, money) to linear equations and solve them", "Can verify solutions by substitution and interpret them in context"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g8.alg.expressions-identities", "title": "Algebraic Expressions and Identities", "grade": 8, "strand": "alg", "description": "You will multiply monomials, binomials and polynomials, and meet the standard identities: (a+b)² = a²+2ab+b², (a−b)² = a²−2ab+b², and (a+b)(a−b) = a²−b². Identities are equalities true for ALL values — and they turn ugly arithmetic like 103² into two-second mental maths.", "prereqs": ["g7.alg.expressions", "g7.num.exponents-intro"], "outcomes": ["Can multiply monomials and binomials, applying exponent rules to variables", "Can expand using the three standard identities and recognise when they apply", "Can distinguish an identity (true for all values) from an equation (true for some)", "Can use identities for fast numeric computation (103², 98², 52 × 48)"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g8.alg.factorisation", "title": "Factorisation of Algebraic Expressions", "grade": 8, "strand": "alg", "description": "Factorisation reverses expansion: rewriting an expression as a product of factors. You will take out common factors, regroup, apply the identities backwards (a² − b² = (a+b)(a−b)), split the middle term of x² + bx + c, and divide expressions cleanly — with a spotlight on the cancellation errors everyone must unlearn.", "prereqs": ["g8.alg.expressions-identities", "g6.num.playing-with-numbers"], "outcomes": ["Can factor out the greatest common monomial factor completely", "Can factorise using identities, especially the difference of squares", "Can factorise trinomials x² + bx + c by splitting the middle term", "Can divide a polynomial by a monomial correctly, term by term"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": []}, {"id": "g8.alg.graphs-intro", "title": "Introduction to Graphs: Coordinates and Linear Graphs", "grade": 8, "strand": "alg", "description": "The coordinate plane turns pairs of numbers into points and relationships into pictures. You will plot points, read line graphs, and draw the graphs of simple linear relationships like y = 2x — seeing for the first time that an equation IS a line. This bridge between algebra and geometry carries all of higher mathematics.", "prereqs": ["g6.num.integers-intro", "g8.alg.linear-equations-1var"], "outcomes": ["Can plot and read points (x, y), respecting the order of coordinates", "Can locate points on the axes and state where axis points belong", "Can check whether a point lies on the graph of a simple equation like y = 2x", "Can interpret real line graphs (distance–time, cost–quantity) including rates as steepness"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g8.geo.quadrilaterals", "title": "Understanding Quadrilaterals: Polygon Angle Sums and Parallelograms", "grade": 8, "strand": "geo", "description": "The interior angles of an n-sided polygon sum to (n−2)×180°, while exterior angles always total 360°. You will use these facts, then dive into the parallelogram family — opposite sides and angles equal, diagonals bisecting each other — and see how rectangle, rhombus and square refine it step by step.", "prereqs": ["g7.geo.triangle-properties", "g6.geo.elementary-shapes"], "outcomes": ["Can compute interior angle sums of polygons via (n−2) × 180° and use the 360° exterior-angle fact", "Can use parallelogram properties (opposite sides/angles equal, adjacent angles supplementary, diagonals bisect each other) to find unknowns", "Can state which extra properties rectangles, rhombuses and squares add", "Can place the special quadrilaterals in a correct hierarchy"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g8.geo.practical-geometry-quads", "title": "Practical Geometry: Constructing Quadrilaterals", "grade": 8, "strand": "geo", "description": "A quadrilateral needs five independent measurements to be pinned down — four sides alone leave it floppy. You will construct quadrilaterals from five given parts (e.g. four sides and a diagonal) by splitting them into two triangles, reusing everything you know about triangle construction.", "prereqs": ["g8.geo.quadrilaterals", "g7.geo.practical-geometry"], "outcomes": ["Can explain why 5 measurements (suitably chosen) determine a quadrilateral while 4 do not", "Can construct quadrilaterals given: 4 sides + 1 diagonal; 3 sides + 2 diagonals; 2 adjacent sides + 3 angles; 3 sides + 2 included angles", "Can decompose the construction into two triangle constructions sharing a diagonal", "Can detect impossible data (triangle inequality failing inside a component triangle)"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g8.geo.visualising-solids", "title": "Visualising Solid Shapes: Views and Euler's Relation", "grade": 8, "strand": "geo", "description": "You will map solids from different viewpoints (top, front, side), read simple maps, and discover Euler's beautiful relation for polyhedra: F + V − E = 2 — faces plus vertices minus edges equals two, for EVERY polyhedron from a cube to a football. It is many students' first universal theorem about 3D space.", "prereqs": ["g7.geo.visualising-solids"], "outcomes": ["Can draw and match top, front and side views of solids and cube arrangements", "Can distinguish polyhedra (flat faces) from non-polyhedra (cylinder, sphere, cone)", "Can verify Euler's relation F + V − E = 2 on prisms and pyramids", "Can use Euler's relation to find a missing count (e.g. faces from V and E)"], "difficulty": 3, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g8.mea.mensuration", "title": "Mensuration: Trapezium, Polygon Areas; Surface Area and Volume", "grade": 8, "strand": "mea", "description": "You will find areas of trapeziums and general quadrilaterals via triangles, then step into 3D: surface areas and volumes of cuboids and cylinders. Keeping 'how much to paint' (surface area) separate from 'how much it holds' (volume) — and their different units — is the chapter's central discipline.", "prereqs": ["g7.mea.perimeter-area", "g5.mea.volume-intuition"], "outcomes": ["Can compute the area of a trapezium as ½(a + b)h and of polygons by triangulation", "Can compute lateral/total surface area of cuboids, cubes and cylinders", "Can compute volumes of cuboids, cubes and cylinders", "Can choose between surface area and volume from context, with correct units (cm² vs cm³)", "Can reason about scaling: doubling an edge multiplies volume by 8"], "difficulty": 3, "est_minutes": 55, "stub": false, "micros": []}, {"id": "g8.dat.data-handling", "title": "Data Handling: Histograms, Pie Charts, Probability Intro", "grade": 8, "strand": "dat", "description": "You will group data into class intervals and draw histograms (bars touching — the scale is continuous), build and read pie charts where slices are proportional shares of 360°, and compute probabilities of equally likely outcomes — learning why a coin has no memory.", "prereqs": ["g7.dat.data-handling-averages"], "outcomes": ["Can group raw data into class intervals and draw/read a histogram", "Can explain why histogram bars touch while bar-graph bars do not", "Can convert data shares into pie-chart angles (fraction × 360°) and read pie charts", "Can compute probabilities as favourable/total for equally likely outcomes, and recognise independence of successive trials"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g9.num.number-systems", "title": "Number Systems: Irrational Numbers, Real Number Line, Rationalisation", "grade": 9, "strand": "num", "description": "Not every number can be written as a fraction: numbers like √2 and π have decimal expansions that never end and never repeat. This node extends the number line to all real numbers, teaches you to spot rational versus irrational numbers from their decimal expansions, to locate irrationals like √2 on the number line, and to simplify expressions with surds by rationalising denominators. It is the foundation for all later algebra, since from now on 'number' means 'real number'.", "prereqs": ["g8.num.rational-numbers", "g8.num.squares-roots", "g8.num.exponents-powers"], "outcomes": ["Can classify a given number as natural, whole, integer, rational or irrational with justification", "Can decide from a decimal expansion (terminating, recurring, non-recurring) whether a number is rational or irrational", "Can represent numbers like √2 and √3 on the number line using right triangles", "Can rationalise denominators of the form 1/(a+b√c) and simplify surd expressions using laws of exponents"], "difficulty": 3, "est_minutes": 80, "stub": false, "micros": []}, {"id": "g9.alg.polynomials", "title": "Polynomials: Zeroes, Remainder and Factor Theorems, Identities", "grade": 9, "strand": "alg", "description": "A polynomial is an expression built from a variable using only addition, subtraction and whole-number powers — the workhorse of algebra. Here you learn to evaluate polynomials, find their zeroes, use the Remainder and Factor Theorems to divide and factorise without long division, and wield algebraic identities like (a+b)², a³+b³ and (a+b+c)² to compute and factorise at speed. Everything from quadratic equations to calculus stands on this node.", "prereqs": ["g8.alg.expressions-identities", "g8.alg.factorisation"], "outcomes": ["Can identify polynomials, state their degree, and classify them as linear, quadratic or cubic", "Can evaluate p(x) at a given value and verify whether a given number is a zero of p(x)", "Can apply the Remainder Theorem (remainder of p(x) ÷ (x−a) is p(a)) and the Factor Theorem to factorise cubics", "Can expand and factorise using standard identities including (a±b)², a²−b², (x+a)(x+b), (a+b+c)² and a³±b³"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g9.alg.linear-equations-2var", "title": "Linear Equations in Two Variables", "grade": 9, "strand": "alg", "description": "An equation like 2x + y = 7 does not have one answer — it has infinitely many solutions, each an ordered pair (x, y), and together they draw a straight line in the Cartesian plane. This node connects algebra to geometry: every solution is a point on the line, and every point on the line is a solution. Mastering this picture prepares you for solving pairs of such equations in Class 10 and for functions and graphs beyond.", "prereqs": ["g8.alg.linear-equations-1var", "g8.alg.graphs-intro", "g9.geo.coordinate-geometry"], "outcomes": ["Can write a linear equation in two variables in the standard form ax + by + c = 0 and identify a, b, c", "Can find several solutions of a given equation and verify whether a given ordered pair is a solution", "Can explain why such an equation has infinitely many solutions and why its graph is a straight line", "Can graph equations including the special forms x = k and y = k"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g9.geo.coordinate-geometry", "title": "Coordinate Geometry: The Cartesian Plane", "grade": 9, "strand": "geo", "description": "René Descartes' big idea: describe every point in the plane with a pair of numbers. This node sets up the Cartesian plane — two perpendicular axes, four quadrants, and the (x, y) address system — and teaches you to plot points, read coordinates, and reason about signs, axes and distances from the axes. It is the bridge on which algebra and geometry meet, and every graph you ever draw lives here.", "prereqs": ["g8.alg.graphs-intro", "g6.num.integers-intro"], "outcomes": ["Can name the axes, origin, quadrants, abscissa and ordinate, and plot any point (x, y) accurately", "Can determine the quadrant or axis on which a point lies from the signs of its coordinates", "Can read off perpendicular distances of a point from the axes", "Can explain why (a, b) and (b, a) are different points when a ≠ b"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g9.geo.euclid", "title": "Introduction to Euclid's Geometry", "grade": 9, "strand": "geo", "description": "Around 300 BCE, Euclid organised all known geometry into a single logical structure: start from a handful of self-evident statements (axioms and postulates) and derive everything else by pure reasoning. This node introduces that deductive game — definitions, axioms, postulates, theorems — and the famous fifth postulate whose questioning eventually gave birth to entirely new geometries. It teaches you what 'proof' means, which is the operating system for the rest of school geometry.", "prereqs": ["g6.geo.basic-ideas"], "outcomes": ["Can distinguish between definitions, axioms/postulates (assumed) and theorems (proved)", "Can state and apply Euclid's axioms (e.g. things equal to the same thing are equal to one another) in simple deductions", "Can state Euclid's postulates, including the fifth, and its equivalent version: through a point not on a line there is exactly one parallel line", "Can justify simple statements (e.g. two distinct lines cannot share more than one point) using axioms"], "difficulty": 2, "est_minutes": 40, "stub": false, "micros": []}, {"id": "g9.geo.lines-angles", "title": "Lines and Angles: Formal Proofs", "grade": 9, "strand": "geo", "description": "You have measured angles before; now you prove things about them. Starting from axioms about linear pairs and vertically opposite angles, this node builds formal arguments about intersecting lines, parallel lines cut by a transversal (corresponding, alternate and co-interior angles), and the angle sum of a triangle. The skill being trained is writing a chain of statements, each justified by a reason — the grammar of all future proofs.", "prereqs": ["g7.geo.lines-angles", "g9.geo.euclid"], "outcomes": ["Can apply the linear pair axiom and prove that vertically opposite angles are equal", "Can identify corresponding, alternate interior and co-interior angle pairs and state their properties for parallel lines", "Can compute unknown angles in figures with parallel lines and transversals, justifying each step", "Can prove and apply the angle sum property of a triangle and the exterior angle theorem"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g9.geo.triangles", "title": "Triangles: Congruence Proofs and Inequalities", "grade": 9, "strand": "geo", "description": "Two triangles are congruent when one fits exactly on the other — and remarkably, you never need to check all six parts. This node proves and applies the congruence criteria (SAS, ASA, AAS, SSS, RHS), uses them to establish properties like 'angles opposite equal sides are equal', and explores triangle inequalities: bigger sides face bigger angles, and any two sides together must out-length the third. These tools power almost every geometry proof that follows.", "prereqs": ["g7.geo.congruence", "g7.geo.triangle-properties", "g9.geo.lines-angles"], "outcomes": ["Can select and apply the appropriate congruence criterion (SAS, ASA, AAS, SSS, RHS) with correct correspondence of vertices", "Can prove that angles opposite equal sides of a triangle are equal, and use the converse", "Can use the triangle inequality to decide whether three lengths can form a triangle", "Can order the angles of a triangle given its sides (and vice versa) using the side-angle relationship"], "difficulty": 4, "est_minutes": 80, "stub": false, "micros": []}, {"id": "g9.geo.quadrilaterals", "title": "Quadrilaterals: Parallelogram Theorems and the Midpoint Theorem", "grade": 9, "strand": "geo", "description": "Parallelograms hide a bundle of always-true facts: opposite sides and angles are equal, diagonals bisect each other — and each fact, remarkably, also works in reverse as a test. This node proves the parallelogram theorems using triangle congruence, learns which conditions guarantee a parallelogram (and which don't), and crowns it with the Midpoint Theorem: the segment joining midpoints of two sides of a triangle is parallel to the third side and half its length.", "prereqs": ["g8.geo.quadrilaterals", "g9.geo.triangles"], "outcomes": ["Can prove and apply properties of a parallelogram: opposite sides equal, opposite angles equal, diagonals bisect each other", "Can decide whether a given condition is sufficient to guarantee that a quadrilateral is a parallelogram", "Can compute unknown angles in parallelograms using co-interior and opposite angle relationships", "Can state, prove and apply the Midpoint Theorem and its converse"], "difficulty": 4, "est_minutes": 70, "stub": false, "micros": []}, {"id": "g9.geo.circles", "title": "Circles: Chords, Arcs and Cyclic Quadrilaterals", "grade": 9, "strand": "geo", "description": "A circle is perfectly symmetric, and that symmetry generates powerful theorems: the perpendicular from the centre bisects a chord, equal chords sit at equal distances from the centre, the angle an arc subtends at the centre is double the angle at the circumference, angles in the same segment are equal, and opposite angles of a cyclic quadrilateral are supplementary. This node proves these results and uses them to crack angle-chasing problems.", "prereqs": ["g9.geo.triangles", "g9.geo.quadrilaterals", "g6.geo.basic-ideas"], "outcomes": ["Can apply chord properties: perpendicular from the centre bisects a chord, and equal chords are equidistant from the centre", "Can use the theorem 'angle at the centre is twice the angle at the circumference subtended by the same arc'", "Can identify and use 'angles in the same segment are equal' and 'angle in a semicircle is 90°'", "Can apply the cyclic quadrilateral property: opposite angles sum to 180°"], "difficulty": 4, "est_minutes": 80, "stub": false, "micros": []}, {"id": "g9.geo.constructions", "title": "Constructions: Bisectors and Triangles", "grade": 9, "strand": "geo", "description": "With only an ungraduated ruler and a compass — no protractor — you can bisect any angle, erect perpendicular bisectors, build 60°, 30°, 90° and 45° exactly, and construct triangles from indirect data such as base, base angle and the sum or difference of the other two sides. Each construction comes with a proof of WHY it works, turning drawing into applied congruence.", "prereqs": ["g6.geo.constructions-intro", "g7.geo.practical-geometry", "g9.geo.triangles"], "outcomes": ["Can bisect a given angle and construct the perpendicular bisector of a segment, and justify both constructions using congruence", "Can construct angles of 60°, 30°, 90°, 45° and their combinations with ruler and compass only", "Can construct a triangle given its base, a base angle, and the sum (or difference) of the other two sides", "Can check the feasibility of a construction using the triangle inequality before starting"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g9.mea.herons-formula", "title": "Heron's Formula", "grade": 9, "strand": "mea", "description": "Area = ½ × base × height is useless when you know all three sides but no height. Heron's formula rescues you: with semi-perimeter s = (a+b+c)/2, the area is √(s(s−a)(s−b)(s−c)) — no heights, no angles, just the sides. This node applies it to triangles and to quadrilaterals that can be split into triangles, a genuinely practical tool for surveyors and anyone measuring land.", "prereqs": ["g7.mea.perimeter-area", "g8.num.squares-roots"], "outcomes": ["Can compute the semi-perimeter and apply Heron's formula to find the area of a triangle from its three sides", "Can simplify the resulting square roots, leaving answers in exact surd form where appropriate", "Can find areas of quadrilaterals by splitting them into triangles with a known diagonal", "Can cross-check Heron's result against ½ × base × height for right triangles"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g9.mea.surface-volume", "title": "Surface Areas and Volumes: Cone, Sphere, Cylinder", "grade": 9, "strand": "mea", "description": "Cylinders, cones and spheres are the curved solids of daily life — pipes, ice-cream cones, footballs. This node derives and applies their surface areas (curved and total) and volumes: cylinder (2πrh, πr²h), cone (πrl, ⅓πr²h) and sphere (4πr², 4/3πr³), including the beautiful facts that a cone is one-third of its cylinder and a sphere is two-thirds of its enclosing cylinder. You also learn to keep slant height l and vertical height h firmly apart.", "prereqs": ["g8.mea.mensuration", "g7.mea.perimeter-area"], "outcomes": ["Can compute curved and total surface areas of cylinders, cones and spheres, choosing the right one for the context", "Can compute volumes of cylinders, cones, spheres and hemispheres", "Can relate slant height, vertical height and radius of a cone by l² = r² + h² and use the correct one in each formula", "Can predict how surface area and volume scale when the radius is doubled or halved"], "difficulty": 3, "est_minutes": 80, "stub": false, "micros": []}, {"id": "g9.dat.statistics", "title": "Statistics: Grouped Data, Histograms, Frequency Polygons", "grade": 9, "strand": "dat", "description": "Raw data is a crowd; statistics gives it a face. This node organises data into ungrouped and grouped frequency distributions, draws and reads bar graphs, histograms (including the subtle case of unequal class widths, where bar AREA carries the frequency) and frequency polygons, and computes class marks. It builds the visual literacy needed to spot the story — and the lie — in a chart.", "prereqs": ["g8.dat.data-handling"], "outcomes": ["Can construct grouped frequency distributions, identifying class limits, class width and class marks", "Can draw and interpret histograms, adjusting bar heights (frequency density) when class widths are unequal", "Can draw a frequency polygon from a histogram or directly from class marks", "Can choose correctly between a bar graph (categorical data) and a histogram (continuous grouped data)"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g9.dat.probability-empirical", "title": "Probability: The Empirical Approach", "grade": 9, "strand": "dat", "description": "Before theory, there is experiment: toss a coin 500 times, count heads, and the fraction of heads is the empirical (experimental) probability. This node defines P(event) = (trials where the event happened)/(total trials), explores how this settles down as trials grow, and establishes the ground rules — probabilities live between 0 and 1, and the probabilities of an event and its complement sum to 1. It is the honest, data-first doorway to the classical probability of Class 10.", "prereqs": ["g8.dat.data-handling", "g7.dat.data-handling-averages"], "outcomes": ["Can compute empirical probabilities from frequency data (coin tosses, dice records, survey tables)", "Can explain why every probability lies between 0 and 1, and use P(not E) = 1 − P(E)", "Can describe how empirical probability stabilises as the number of trials increases", "Can distinguish what a probability claims about the long run from what happens in any short run"], "difficulty": 2, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g10.num.real-numbers", "title": "Real Numbers: Fundamental Theorem of Arithmetic, Irrationality Proofs", "grade": 10, "strand": "num", "description": "Every integer greater than 1 factors into primes in exactly one way — the Fundamental Theorem of Arithmetic. From this single fact flow practical tools (HCF and LCM via prime factorisation, and the relation HCF × LCM = product of the two numbers), a crisp test for which fractions have terminating decimals, and elegant proofs by contradiction that numbers like √2, √3 and √5 are irrational. This node upgrades your Class 9 acquaintance with irrationals into actual proof.", "prereqs": ["g9.num.number-systems", "g6.num.playing-with-numbers"], "outcomes": ["Can find HCF and LCM of two numbers by prime factorisation and verify HCF × LCM = product of the numbers", "Can prove the irrationality of numbers like √2, √5, and combinations like 3 + 2√5, by contradiction", "Can decide, without dividing, whether a rational number p/q has a terminating or non-terminating recurring decimal expansion (after reducing, q must be of the form 2ᵐ5ⁿ)", "Can apply HCF/LCM reasoning to problems about bells tolling together, stacking, and circular tracks"], "difficulty": 3, "est_minutes": 70, "stub": false, "micros": []}, {"id": "g10.alg.polynomials", "title": "Polynomials: Zeroes and Coefficients", "grade": 10, "strand": "alg", "description": "A quadratic's zeroes are not random: their sum is −b/a and their product is c/a, straight from the coefficients. This node connects the geometry (zeroes are where the graph crosses the x-axis) with the algebra (factoring, and building a quadratic back from its zeroes), so you can read a polynomial's roots from its graph and its graph from its roots. It is the launchpad for quadratic equations.", "prereqs": ["g9.alg.polynomials"], "outcomes": ["Can find the zeroes of a quadratic polynomial by factorisation and verify the relationships sum = −b/a, product = c/a", "Can read the number of zeroes of a polynomial from the number of times its graph meets the x-axis", "Can construct a quadratic polynomial from a given sum and product of zeroes", "Can evaluate symmetric expressions in the zeroes (α + β, αβ, α² + β²) without finding the zeroes themselves"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g10.alg.linear-pair-2var", "title": "Pair of Linear Equations in Two Variables", "grade": 10, "strand": "alg", "description": "Two conditions, two unknowns: a pair of linear equations is two lines on the same plane, and everything depends on how those lines relate — crossing (one solution), parallel (none), or coincident (infinitely many), which the coefficient ratios a₁/a₂, b₁/b₂, c₁/c₂ diagnose without drawing. You will solve systems by substitution and elimination and use them to crack age, cost, speed and fraction word problems — the single most examined chapter of Class 10 algebra.", "prereqs": ["g9.alg.linear-equations-2var", "g8.alg.linear-equations-1var"], "outcomes": ["Can classify a pair of linear equations as consistent (unique or infinite solutions) or inconsistent using coefficient ratios", "Can solve a pair of linear equations by substitution and by elimination, choosing the more efficient method", "Can interpret the solution graphically as the intersection of two lines", "Can translate word problems (ages, costs, digits, speeds, fractions) into pairs of equations and solve them"], "difficulty": 4, "est_minutes": 85, "stub": false, "micros": []}, {"id": "g10.alg.quadratic-equations", "title": "Quadratic Equations: Factoring, Formula, Discriminant", "grade": 10, "strand": "alg", "description": "When a problem multiplies an unknown by itself — areas, projectiles, speed-time — you get a quadratic equation ax² + bx + c = 0. This node solves them three ways (factorisation, completing the square, and the quadratic formula) and reads the discriminant D = b² − 4ac as a forecast: D > 0 two distinct real roots, D = 0 two equal roots, D < 0 no real roots. It is the first equation family where 'how many solutions?' becomes a serious question.", "prereqs": ["g10.alg.polynomials", "g8.alg.factorisation", "g8.num.squares-roots"], "outcomes": ["Can solve quadratic equations by factorisation using the zero-product principle", "Can apply the quadratic formula accurately, including sign handling for negative b and c", "Can compute the discriminant and state the nature of the roots without solving", "Can model word problems (areas, ages, speed-time) as quadratic equations, solve, and reject inadmissible roots"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g10.alg.arithmetic-progressions", "title": "Arithmetic Progressions: nth Term and Sum", "grade": 10, "strand": "alg", "description": "Add the same amount each step — salaries with fixed annual raises, theatre rows growing seat by seat, EMI schedules — and you get an arithmetic progression. This node nails the two master formulas: the nth term aₙ = a + (n−1)d and the sum Sₙ = n/2[2a + (n−1)d] = n/2(first + last), plus the art of recognising when a situation IS an AP and when it merely looks like one.", "prereqs": ["g8.alg.linear-equations-1var", "g7.alg.expressions"], "outcomes": ["Can identify whether a sequence is an AP by checking for a constant common difference", "Can compute any term of an AP using aₙ = a + (n−1)d, and solve for a, d or n given the others", "Can compute the sum of the first n terms using both forms of the sum formula", "Can model real situations (instalments, stacked rows, salary increments) as APs and answer questions about them"], "difficulty": 3, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g10.geo.triangles-similarity", "title": "Triangles: Similarity, Basic Proportionality Theorem, Pythagoras", "grade": 10, "strand": "geo", "description": "Similar figures have the same shape at different sizes: angles match, and corresponding sides scale by one common ratio. This node proves the Basic Proportionality (Thales) Theorem — a line parallel to one side of a triangle divides the other two sides proportionally — establishes the AA, SSS and SAS similarity criteria, and puts them to work, including in proofs and applications of the Pythagoras theorem. Similarity is the mathematics of maps, models, shadows and zoom.", "prereqs": ["g9.geo.triangles", "g7.geo.triangle-properties", "g6.num.ratio-proportion"], "outcomes": ["Can state and apply the Basic Proportionality Theorem and its converse to compute segment lengths", "Can prove triangles similar using AA, SSS or SAS similarity criteria with correct correspondence", "Can compute unknown sides of similar triangles using the scale factor (multiplicative, not additive)", "Can apply the Pythagoras theorem and its converse in computations and proofs"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g10.geo.coordinate-geometry", "title": "Coordinate Geometry: Distance, Section Formula, Areas", "grade": 10, "strand": "geo", "description": "Once points have coordinates, geometry becomes computation. The distance formula (Pythagoras in disguise) measures lengths, the section formula finds the point dividing a segment in a given ratio (midpoint as the friendly special case), and a determinant-style formula computes triangle areas — including the test for three points lying on one line. This node turns classification problems ('is this a rhombus?') into arithmetic.", "prereqs": ["g9.geo.coordinate-geometry", "g10.geo.triangles-similarity"], "outcomes": ["Can compute the distance between two points and use it to classify triangles and quadrilaterals", "Can apply the section formula to find a point dividing a segment in ratio m:n, and the midpoint as a special case", "Can find the area of a triangle from its vertices and use area = 0 as a collinearity test", "Can solve reverse problems: find a coordinate or ratio given a distance, midpoint or section condition"], "difficulty": 3, "est_minutes": 70, "stub": false, "micros": []}, {"id": "g10.geo.circles-tangents", "title": "Circles: Tangents and Their Properties", "grade": 10, "strand": "geo", "description": "A tangent kisses a circle at exactly one point — and at that point it stands perfectly perpendicular to the radius. From this single fact plus congruence comes the second gem: the two tangents drawn from an external point are equal in length. This short, elegant node proves both theorems and applies them to compute lengths and angles in tangent configurations, from bicycle chains to belt drives.", "prereqs": ["g9.geo.circles", "g9.geo.triangles"], "outcomes": ["Can define a tangent and distinguish it from a secant and a chord", "Can apply the theorem 'the tangent at any point is perpendicular to the radius through that point' in computations", "Can prove and use the equality of the two tangent lengths from an external point", "Can solve mixed problems combining tangents with Pythagoras and angle-chasing (e.g. the angle between two tangents)"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g10.geo.constructions", "title": "Constructions: Dividing Segments and Drawing Tangents", "grade": 10, "strand": "geo", "description": "Class 10 constructions are applied similarity and circle theory: divide a segment in any given ratio m:n, construct a triangle similar to a given one with a given scale factor, and draw the pair of tangents to a circle from an external point. Each construction must be justified — the parallel-line division leans on the Basic Proportionality Theorem, and the tangent construction leans on the angle in a semicircle being 90°.", "prereqs": ["g9.geo.constructions", "g10.geo.triangles-similarity", "g10.geo.circles-tangents"], "outcomes": ["Can divide a line segment internally in a given ratio m:n and justify the construction using the Basic Proportionality Theorem", "Can construct a triangle similar to a given triangle with a given scale factor (both smaller and larger than 1)", "Can construct the pair of tangents to a circle from an external point and justify why the construction works", "Can explain each construction's justification rather than merely reproduce its steps"], "difficulty": 3, "est_minutes": 50, "stub": false, "micros": []}, {"id": "g10.tri.intro", "title": "Introduction to Trigonometry: Ratios and Identities", "grade": 10, "strand": "tri", "description": "Trigonometry begins with a right triangle and one acute angle: the ratios of its sides — sine, cosine, tangent and their reciprocals — depend only on the angle, not on the triangle's size. This node defines the six ratios, computes exact values at 0°, 30°, 45°, 60° and 90°, and proves and applies the fundamental identity sin²θ + cos²θ = 1 and its companions. These ratios are how astronomers measured the unreachable — and how you will, too.", "prereqs": ["g10.geo.triangles-similarity", "g7.geo.triangle-properties", "g6.num.ratio-proportion"], "outcomes": ["Can define sin, cos, tan (and their reciprocals) for an acute angle of a right triangle and compute them from given sides", "Can recall and use the exact values of the trigonometric ratios at 0°, 30°, 45°, 60° and 90°", "Can find the remaining ratios when one ratio is given, using Pythagoras", "Can prove and apply the identities sin²θ + cos²θ = 1, 1 + tan²θ = sec²θ, 1 + cot²θ = cosec²θ"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g10.tri.applications", "title": "Applications of Trigonometry: Heights and Distances", "grade": 10, "strand": "tri", "description": "How tall is the tower you cannot climb, how far the ship you cannot reach? Stand somewhere, measure an angle of elevation or depression, and let trigonometry do the climbing. This node turns word descriptions into right-triangle diagrams, chooses the ratio that links the known and unknown sides (usually tan), and solves single- and double-triangle problems — the survey engineer's daily bread since long before lasers.", "prereqs": ["g10.tri.intro"], "outcomes": ["Can define and correctly place angles of elevation and depression in a diagram, both measured from the HORIZONTAL", "Can draw a correct right-triangle model from a verbal description, including observer height when given", "Can choose the appropriate trigonometric ratio and compute heights and distances using exact values (30°, 45°, 60°)", "Can solve two-triangle problems (two observation points, or two objects) by combining equations"], "difficulty": 4, "est_minutes": 70, "stub": false, "micros": []}, {"id": "g10.mea.areas-circles", "title": "Areas Related to Circles: Sectors and Segments", "grade": 10, "strand": "mea", "description": "A sector is a pizza slice, a segment is what a chord cuts off. This node computes arc lengths and sector areas as fractions (θ/360) of the whole circle's circumference and area, finds segment areas by subtracting the triangle from its sector, and handles combinations — flower beds on square lawns, wiper sweeps, and designs of overlapping circles. One idea powers it all: an angle's share of 360° is its share of the circle.", "prereqs": ["g7.mea.perimeter-area", "g6.num.ratio-proportion"], "outcomes": ["Can compute the arc length of a sector as (θ/360) × 2πr and its area as (θ/360) × πr²", "Can compute the perimeter of a sector (arc + two radii), distinguishing it from the arc length", "Can compute the area of a minor segment as sector area minus triangle area", "Can solve combination problems: sweeps of wiper blades, designs from squares and circles, grazing regions"], "difficulty": 3, "est_minutes": 65, "stub": false, "micros": []}, {"id": "g10.mea.surface-volume", "title": "Surface Areas and Volumes: Combined Solids", "grade": 10, "strand": "mea", "description": "Real objects are combinations: a capsule is a cylinder with hemispherical ends, an ice-cream cone is a cone crowned by a hemisphere, a tent is a cylinder wearing a conical hat. This node computes surface areas of such composites (counting only the surfaces that actually show — glued faces vanish) and their volumes (which simply add), including melt-and-recast problems where one shape's volume becomes another's. It is Class 9 mensuration graduating into engineering.", "prereqs": ["g9.mea.surface-volume"], "outcomes": ["Can compute the surface area of a combined solid by summing only the EXPOSED surfaces of each component", "Can compute the volume of a combined solid by adding component volumes", "Can solve conversion problems (melting, recasting, pouring) using conservation of volume", "Can select the correct component formulas (CSA vs TSA, hemisphere vs sphere) for each part of a composite"], "difficulty": 4, "est_minutes": 80, "stub": false, "micros": []}, {"id": "g10.dat.statistics", "title": "Statistics: Mean, Median, Mode of Grouped Data; Ogives", "grade": 10, "strand": "dat", "description": "When data arrives pre-grouped into classes, the exact values are gone — so mean, median and mode must be estimated from the group structure: mean via class marks weighted by frequencies, median via the cumulative-frequency formula (or read off an ogive), and mode via the modal-class formula. This node teaches all three, the empirical bridge mode ≈ 3(median) − 2(mean), and when each measure is the right summary to report.", "prereqs": ["g9.dat.statistics", "g7.dat.data-handling-averages"], "outcomes": ["Can compute the mean of grouped data by the direct and assumed-mean methods using class marks and frequencies", "Can identify the modal class and median class of a grouped distribution", "Can compute the median of grouped data with the formula, and read it from an ogive at n/2", "Can apply the empirical relationship mode = 3(median) − 2(mean) and judge which average best represents a dataset"], "difficulty": 3, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g10.dat.probability", "title": "Probability: The Classical Approach", "grade": 10, "strand": "dat", "description": "When all outcomes are equally likely — a fair coin, an unloaded die, a well-shuffled deck — probability needs no experiment: P(E) = (favourable outcomes)/(total outcomes). This node counts outcomes carefully (including for two dice and two coins, where 'equally likely' takes real thought), uses complements, and locks in the boundaries: probabilities live in [0, 1], with 0 for impossible and 1 for certain events. It is the theoretical twin of Class 9's empirical approach.", "prereqs": ["g9.dat.probability-empirical"], "outcomes": ["Can compute classical probabilities by counting equally likely outcomes (coins, dice, cards, balls in bags)", "Can construct the full outcome set for compound experiments (two coins, two dice) and count favourable cases correctly", "Can use P(not E) = 1 − P(E) and identify impossible, sure and elementary events", "Can explain what a probability statement predicts about long-run frequency, and what it does not promise short-term"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g11.alg.sets", "title": "Sets: Representation, Operations, Venn Diagrams", "grade": 11, "strand": "alg", "description": "Sets are the language in which the rest of higher mathematics is written: collections of well-defined objects, described in roster or set-builder form. You will operate on sets with union, intersection, difference and complement, picture them with Venn diagrams, and use counting rules like n(A∪B) = n(A) + n(B) − n(A∩B). Mastering this vocabulary pays off immediately in relations, functions and probability.", "prereqs": ["g9.num.number-systems"], "outcomes": ["Can write a set in roster and set-builder form and decide whether a collection is well-defined", "Can distinguish element membership (∈) from subset inclusion (⊂) and list all subsets of a small set", "Can compute union, intersection, difference and complement, and represent them on Venn diagrams", "Can use n(A∪B) = n(A) + n(B) − n(A∩B) to solve survey-style counting problems", "Can work with intervals of real numbers as sets and take complements within a universal set"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g11.alg.relations-functions", "title": "Relations and Functions: Domain, Range, Standard Functions", "grade": 11, "strand": "alg", "description": "A relation pairs elements of one set with another via the Cartesian product; a function is the special relation where every input gets exactly one output. You will find domains and ranges, and meet the standard function family — identity, constant, polynomial, rational, modulus, signum, greatest integer — with their graphs. Functions are the central objects of calculus, so fluency here directly powers limits and derivatives.", "prereqs": ["g11.alg.sets", "g8.alg.graphs-intro", "g9.geo.coordinate-geometry"], "outcomes": ["Can form Cartesian products and count/list relations from A to B", "Can decide whether a given relation (as pairs, arrow diagram or graph) is a function, citing the definition", "Can find the domain and range of algebraic functions involving fractions and square roots", "Can sketch and read graphs of identity, constant, modulus, signum and greatest-integer functions", "Can perform algebra of functions: sum, difference, product, quotient with correct domains"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g11.tri.functions", "title": "Trigonometric Functions: Radians, Identities, Graphs, Equations", "grade": 11, "strand": "tri", "description": "Trigonometry graduates from right-triangle ratios to genuine functions of a real number: angles in radians, the unit circle, signs in all four quadrants, and the wave-like graphs of sine and cosine. You will wield compound-angle and multiple-angle identities like sin(A±B), cos 2x, and solve trigonometric equations in full generality. These functions model every periodic phenomenon — sound, light, tides, alternating current — and their limits and derivatives are pillars of calculus.", "prereqs": ["g10.tri.intro", "g11.alg.relations-functions"], "outcomes": ["Can convert between degrees and radians and interpret radian measure as arc length over radius", "Can evaluate all six trigonometric functions at standard angles in any quadrant using the unit circle and sign rules", "Can sketch and interpret the graphs of sin, cos and tan, identifying period, amplitude and asymptotes", "Can apply compound-angle and double-angle identities such as sin(A+B), cos(A+B) and cos 2x to simplify and evaluate expressions", "Can write general solutions of equations like sin x = k, cos x = k, tan x = k"], "difficulty": 4, "est_minutes": 120, "stub": false, "micros": []}, {"id": "g11.num.complex-quadratic", "title": "Complex Numbers and Quadratic Equations", "grade": 11, "strand": "num", "description": "To solve x² + 1 = 0 we extend the real numbers with i, where i² = −1, obtaining complex numbers a + bi with their own arithmetic, conjugates and modulus. Quadratic equations with negative discriminant now have two (conjugate) complex roots — the number system finally makes every quadratic solvable. Complex numbers are indispensable in AC circuit analysis, signal processing and quantum physics.", "prereqs": ["g10.alg.quadratic-equations", "g9.num.number-systems"], "outcomes": ["Can compute powers of i by reducing exponents modulo 4", "Can add, subtract, multiply and divide complex numbers, using the conjugate to rationalise quotients", "Can find the modulus and conjugate of a complex number and interpret a + bi as a point in the Argand plane", "Can solve quadratic equations with negative discriminant and express roots as conjugate pairs", "Can explain why rules like √a·√b = √(ab) fail when both a and b are negative"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g11.alg.linear-inequalities", "title": "Linear Inequalities", "grade": 11, "strand": "alg", "description": "Inequalities describe ranges rather than single answers: solving them uses equation-like moves plus one crucial twist — multiplying or dividing by a negative number reverses the inequality sign. You will express solutions as intervals on the number line and handle systems of simultaneous inequalities. This is the toolkit behind constraints everywhere: budgets, safety limits, eligibility cut-offs, and later, linear programming.", "prereqs": ["g8.alg.linear-equations-1var", "g9.alg.linear-equations-2var"], "outcomes": ["Can solve linear inequalities in one variable, reversing the sign when multiplying/dividing by a negative", "Can express solution sets in interval notation and graph them on the number line", "Can solve a pair of simultaneous inequalities and intersect the solution sets", "Can translate word problems (marks, budgets, ranges) into inequalities and interpret the solution in context"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g11.alg.permutations-combinations", "title": "Permutations and Combinations", "grade": 11, "strand": "alg", "description": "Counting without listing: the fundamental principle of counting multiplies choices made in sequence, factorials count arrangements, and the twin tools nPr and nCr count ordered selections versus unordered ones. The single most important skill is deciding whether order matters. These techniques power probability, the binomial theorem, and real questions from passwords to tournament fixtures.", "prereqs": ["g5.num.mult-div-large", "g7.alg.expressions"], "outcomes": ["Can apply the multiplication principle to multi-stage choice problems and the addition principle to exclusive cases", "Can compute and manipulate factorials, nPr and nCr, including simplifying quotients of factorials", "Can decide from context whether a problem needs permutations (order matters) or combinations (order doesn't)", "Can count arrangements with repeated objects (e.g. letters of APPLE) and selections with simple restrictions"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g11.alg.binomial-theorem", "title": "Binomial Theorem", "grade": 11, "strand": "alg", "description": "The binomial theorem expands (a + b)ⁿ without multiplying it out: each term is nCr a^(n−r) b^r, with coefficients readable from Pascal's triangle. You will find general terms, middle terms and specific coefficients, and handle expansions like (x − 2y)⁷ where signs alternate. It is the bridge between combinatorics and algebra, and later feeds probability distributions and approximations.", "prereqs": ["g11.alg.permutations-combinations", "g8.alg.expressions-identities", "g7.num.exponents-intro"], "outcomes": ["Can state and apply the binomial theorem for positive integral n, connecting coefficients to Pascal's triangle and nCr", "Can write the general term T(r+1) = nCr a^(n−r) b^r and use it to find any required term or coefficient", "Can handle expansions with negative or coefficient-bearing terms like (x − 2y)⁷ and (2x + 3)⁵, applying powers to the whole term", "Can count terms in an expansion and locate middle term(s)"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g11.alg.sequences-series", "title": "Sequences and Series: AP, GP, AM-GM, Special Sums", "grade": 11, "strand": "alg", "description": "Sequences follow rules; series add them up. Building on arithmetic progressions, you now master geometric progressions — nth term arⁿ⁻¹, finite sums, and the beautiful infinite sum a/(1−r) when |r| < 1 — plus the AM ≥ GM inequality and formulas for Σn, Σn², Σn³. Growth by a constant ratio is the mathematics of compound interest, population growth and radioactive decay.", "prereqs": ["g10.alg.arithmetic-progressions", "g7.num.exponents-intro"], "outcomes": ["Can identify whether a sequence is an AP, a GP or neither, and find common difference/ratio", "Can compute the nth term and the sum of n terms of a GP, and insert geometric means", "Can determine when an infinite GP has a finite sum and compute S∞ = a/(1−r)", "Can apply AM ≥ GM for two positive numbers and use Σn, Σn², Σn³ to evaluate special series"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g11.geo.straight-lines", "title": "Straight Lines: Slope, Forms of Equations, Distance", "grade": 11, "strand": "geo", "description": "Coordinate geometry turns lines into equations: slope measures steepness as tan of the inclination, and a line can be written in point-slope, two-point, slope-intercept, intercept or general form. Parallel lines share slopes; perpendicular slopes multiply to −1; and the distance from a point to a line has a crisp formula. This algebra-geometry dictionary is the foundation for conic sections, calculus tangents, and linear programming.", "prereqs": ["g10.geo.coordinate-geometry", "g9.alg.linear-equations-2var", "g10.tri.intro"], "outcomes": ["Can compute the slope of a line from two points or from its inclination, and interpret zero vs undefined slope", "Can write the equation of a line in point-slope, slope-intercept, two-point, intercept and general forms and convert between them", "Can apply parallelism (equal slopes) and perpendicularity (m₁m₂ = −1) conditions", "Can compute the distance from a point to a line and the distance between parallel lines"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g11.geo.conic-sections", "title": "Conic Sections: Circle, Parabola, Ellipse, Hyperbola", "grade": 11, "strand": "geo", "description": "Slice a double cone at different angles and you get circles, parabolas, ellipses and hyperbolas — a single family of curves with standard equations: x² + y² = r², y² = 4ax, x²/a² + y²/b² = 1, x²/a² − y²/b² = 1. You will extract centres, foci, vertices, directrices, axes and eccentricity from these equations. Conics are the shapes of planetary orbits, satellite dishes, headlight reflectors and suspension-bridge cables.", "prereqs": ["g11.geo.straight-lines", "g10.alg.quadratic-equations"], "outcomes": ["Can write the equation of a circle from centre and radius, and complete the square to find them from the general form", "Can identify the focus, directrix, axis and latus rectum of a parabola in any of the four standard orientations", "Can find vertices, foci, eccentricity and axes lengths for ellipses and hyperbolas in standard form, using c² = a² − b² or c² = a² + b² appropriately", "Can classify which conic a given second-degree equation in standard form represents"], "difficulty": 4, "est_minutes": 120, "stub": false, "micros": []}, {"id": "g11.vec.intro-3d", "title": "Introduction to Three-Dimensional Geometry", "grade": 11, "strand": "vec", "description": "Adding a z-axis turns the coordinate plane into coordinate space: points become ordered triples (x, y, z), space splits into eight octants, and the familiar tools upgrade — distance becomes √(Δx² + Δy² + Δz²) and the section formula gains a third coordinate. Thinking in 3D coordinates is the gateway to vectors, planes and lines in space, and to how GPS, drones and graphics engines locate anything in the world.", "prereqs": ["g10.geo.coordinate-geometry"], "outcomes": ["Can locate and interpret points (x, y, z), including which coordinate planes and octants they relate to", "Can state the coordinates of points on the axes and coordinate planes (which coordinates vanish where)", "Can compute the distance between two points in space and use it to classify triangles or verify collinearity", "Can apply the section formula (internal division) and midpoint formula in 3D"], "difficulty": 3, "est_minutes": 45, "stub": false, "micros": []}, {"id": "g11.cal.limits-derivatives", "title": "Limits and Derivatives", "grade": 11, "strand": "cal", "description": "Calculus begins here: a limit captures the value a function approaches — which may exist even where the function itself is undefined, as in (x²−4)/(x−2) at x = 2. The derivative is a limit of slopes of secants, giving the exact instantaneous rate of change and the slope of the tangent line. You will evaluate algebraic and trigonometric limits (including sin x/x → 1), differentiate from first principles, and use the sum, product and quotient rules. Every 'rate' in science — velocity, current, growth — is a derivative.", "prereqs": ["g11.alg.relations-functions", "g10.alg.quadratic-equations", "g11.tri.functions", "g11.geo.straight-lines"], "outcomes": ["Can explain a limit intuitively via left- and right-hand approach, and evaluate limits by substitution where valid", "Can resolve 0/0 forms by factoring, rationalising, or standard limits like lim (xⁿ−aⁿ)/(x−a) = naⁿ⁻¹ and lim sin x/x = 1", "Can compute a derivative from first principles as the limit of a difference quotient", "Can interpret the derivative as instantaneous rate of change and as the slope of the tangent line", "Can differentiate polynomials and trigonometric functions using sum, product and quotient rules"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": []}, {"id": "g11.dat.statistics", "title": "Statistics: Measures of Dispersion, Variance, Standard Deviation", "grade": 11, "strand": "dat", "description": "Two datasets can share a mean yet behave completely differently — dispersion measures how spread out the data is. You will compute range, mean deviation, variance and standard deviation for ungrouped and grouped data, and compare the consistency of two datasets using the coefficient of variation. Standard deviation is the workhorse of real analytics, from batting consistency to quality control and finance risk.", "prereqs": ["g10.dat.statistics"], "outcomes": ["Can compute range, mean deviation (about mean or median), variance and standard deviation for ungrouped and grouped data", "Can explain why deviations are squared (or absolute-valued) — raw deviations from the mean always sum to zero", "Can predict the effect on mean, variance and SD of adding a constant to, or scaling, every observation", "Can compare consistency of two datasets with different means using the coefficient of variation CV = (σ/x̄)×100"], "difficulty": 3, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g11.dat.probability", "title": "Probability: Random Experiments and the Axiomatic Approach", "grade": 11, "strand": "dat", "description": "Probability is rebuilt on set theory: a random experiment has a sample space, events are subsets, and probability is a function obeying three axioms — non-negativity, P(S) = 1, and additivity for mutually exclusive events. From these flow the complement rule P(not A) = 1 − P(A) and the addition rule P(A∪B) = P(A) + P(B) − P(A∩B). This foundation supports everything from weather forecasts to insurance and machine learning.", "prereqs": ["g10.dat.probability", "g11.alg.sets", "g11.alg.permutations-combinations"], "outcomes": ["Can describe sample spaces and events as sets for experiments like coin tosses, dice and card draws", "Can identify mutually exclusive and exhaustive events and state the axioms of probability", "Can apply the complement rule and the addition rule P(A∪B) = P(A) + P(B) − P(A∩B)", "Can combine counting techniques (permutations/combinations) with equally-likely outcomes to compute probabilities", "Can recognise impossible probability values (outside [0, 1])"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g12.alg.relations-functions", "title": "Relations and Functions: Types, Composition, Invertibility", "grade": 12, "strand": "alg", "description": "Functions acquire structure: relations can be reflexive, symmetric, transitive (equivalence relations), and functions can be one-one (injective), onto (surjective) or both (bijective). Composition chains functions together — (g∘f)(x) = g(f(x)) — and exactly the bijective functions can be undone by an inverse. Invertibility is the deep idea behind every 'decode', 'undo' and 'solve for x' in mathematics, and behind encryption itself.", "prereqs": ["g11.alg.relations-functions", "g11.alg.sets"], "outcomes": ["Can test a relation for reflexivity, symmetry and transitivity and identify equivalence relations and their classes", "Can prove or disprove that a function is one-one and/or onto, with counterexamples where needed", "Can compute compositions g∘f and f∘g, respecting order, and give examples where they differ", "Can decide whether a function is invertible and find f⁻¹ explicitly for simple bijections", "Can restrict domain/codomain to make a non-invertible function invertible"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g12.tri.inverse-functions", "title": "Inverse Trigonometric Functions", "grade": 12, "strand": "tri", "description": "Sine, cosine and tangent are periodic, so they can only be inverted after restricting to principal branches: sin⁻¹ maps [−1,1] to [−π/2, π/2], cos⁻¹ to [0, π], tan⁻¹ to (−π/2, π/2). You will evaluate principal values, simplify expressions like sin⁻¹(sin x) — which is NOT always x — and use identities such as sin⁻¹x + cos⁻¹x = π/2. These functions are how calculators, surveyors and navigation systems recover angles from ratios, and their derivatives unlock whole families of integrals.", "prereqs": ["g11.tri.functions", "g12.alg.relations-functions"], "outcomes": ["Can state the principal-value branches (domain and range) of sin⁻¹, cos⁻¹ and tan⁻¹", "Can evaluate principal values such as sin⁻¹(1/2), cos⁻¹(−1/2), tan⁻¹(−1)", "Can simplify sin⁻¹(sin x) and cos⁻¹(cos x) when x lies outside the principal branch", "Can apply identities like sin⁻¹x + cos⁻¹x = π/2 and interpret graphs of inverse trig functions as reflections in y = x"], "difficulty": 4, "est_minutes": 75, "stub": false, "micros": []}, {"id": "g12.alg.matrices", "title": "Matrices: Operations, Transpose, Invertibility", "grade": 12, "strand": "alg", "description": "A matrix is a rectangular array of numbers that adds entry-wise but multiplies by a row-into-column rule — an operation that is famously NOT commutative and defined only when inner dimensions match. You will master matrix algebra, transposes, symmetric and skew-symmetric matrices, and meet invertible matrices. Matrices encode simultaneous equations, graphics transformations, network links and the entire machinery of modern machine learning.", "prereqs": ["g8.alg.expressions-identities", "g10.alg.linear-pair-2var"], "outcomes": ["Can state the order of a matrix and decide when sums and products are defined", "Can add, scalar-multiply and multiply matrices using the row-by-column rule", "Can give examples showing AB ≠ BA and explain why matrix algebra identities differ from number algebra", "Can compute transposes and classify matrices as symmetric or skew-symmetric", "Can explain why AB = O does not force A = O or B = O, and recognise identity and invertible matrices"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g12.alg.determinants", "title": "Determinants: Properties, Adjoint, Inverse, Solving Systems", "grade": 12, "strand": "alg", "description": "The determinant condenses a square matrix into a single number that decides everything: invertibility (|A| ≠ 0), the area/volume scaling of the transformation, and solvability of linear systems. You will evaluate 2×2 and 3×3 determinants by cofactor expansion, exploit row/column properties, build inverses via the adjoint A⁻¹ = adj(A)/|A|, and solve systems by the matrix method. It is the algebraic gatekeeper between unique solutions and degeneracy.", "prereqs": ["g12.alg.matrices", "g10.alg.linear-pair-2var"], "outcomes": ["Can evaluate 2×2 and 3×3 determinants by cofactor expansion along any row or column", "Can apply determinant properties: effect of row swaps, common factors, identical rows, and |kA| = kⁿ|A|", "Can compute minors, cofactors and the adjoint, and find A⁻¹ = adj(A)/|A| when |A| ≠ 0", "Can use determinants to test consistency and solve systems of linear equations by the matrix method", "Can interpret |A| = 0 as the matrix being singular (non-invertible) and compute areas of triangles via determinants"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g12.cal.continuity-differentiability", "title": "Continuity and Differentiability", "grade": 12, "strand": "cal", "description": "Continuity at a point demands three things: f(a) exists, the limit exists, and they are equal — 'the pen never leaves the paper'. Differentiability is stronger: the graph must also be smooth, so |x| is continuous everywhere yet not differentiable at its corner. You will test piecewise functions, then differentiate everything in sight — composites via the chain rule, implicit relations, exponential and logarithmic functions, and parametric forms. This is the technical engine room of calculus.", "prereqs": ["g11.cal.limits-derivatives", "g12.alg.relations-functions", "g12.tri.inverse-functions"], "outcomes": ["Can test continuity at a point via left limit, right limit and function value, including for piecewise functions", "Can determine parameter values that make a piecewise function continuous", "Can explain with examples why differentiability implies continuity but not conversely (|x| at 0)", "Can differentiate composite functions with the chain rule, including trig, exponential and logarithmic compositions", "Can perform implicit differentiation, logarithmic differentiation and parametric differentiation, and compute second derivatives"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": []}, {"id": "g12.cal.applications-derivatives", "title": "Applications of Derivatives: Rates, Monotonicity, Maxima and Minima", "grade": 12, "strand": "cal", "description": "Derivatives go to work: related rates connect dA/dt to dr/dt through the chain rule; the sign of f′ tells where a function increases or decreases; and critical points, filtered through the first- or second-derivative test, locate maxima and minima. The crown jewels are optimisation problems — largest area, least cost, fastest route. This chapter is where calculus starts earning its keep in physics, economics and engineering.", "prereqs": ["g12.cal.continuity-differentiability", "g10.alg.quadratic-equations"], "outcomes": ["Can solve related-rates problems by differentiating a geometric relation with respect to time", "Can determine intervals of increase and decrease from the sign of f′", "Can find critical points and classify them using the first- or second-derivative test", "Can recognise critical points that are NOT extrema (e.g. x³ at 0) and check endpoints for absolute extrema on closed intervals", "Can set up and solve optimisation word problems, verifying the nature of the optimum"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": []}, {"id": "g12.cal.integrals", "title": "Integrals: Techniques and the Fundamental Theorem of Calculus", "grade": 12, "strand": "cal", "description": "Integration reverses differentiation: an indefinite integral is a whole family of antiderivatives, differing by the constant C. You will build a toolkit — substitution, integration by parts, partial fractions, and standard forms leading to logs and inverse trig — then meet the Fundamental Theorem of Calculus, which computes definite integrals as F(b) − F(a) and welds together the tangent problem and the area problem. It is arguably the single most powerful equation in mathematics.", "prereqs": ["g12.cal.continuity-differentiability", "g11.cal.limits-derivatives", "g12.tri.inverse-functions"], "outcomes": ["Can find antiderivatives of standard functions and always include the constant of integration", "Can integrate by substitution, recognising when an integrand contains a function and its derivative", "Can integrate by parts, choosing u by the ILATE heuristic, and handle products like x·eˣ", "Can evaluate definite integrals via the Fundamental Theorem as F(b) − F(a), respecting order and sign", "Can use partial fractions and properties of definite integrals (e.g. ∫₀ᵃ f(x)dx = ∫₀ᵃ f(a−x)dx) to simplify evaluation"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": []}, {"id": "g12.cal.applications-integrals", "title": "Applications of Integrals: Areas Under Curves", "grade": 12, "strand": "cal", "description": "The definite integral becomes a measuring tool: the area under a curve is ∫y dx, the area between two curves is the integral of (upper − lower), and regions bounded by parabolas, circles and lines yield to careful setup. The crucial subtlety is that a raw definite integral counts area below the x-axis as negative — geometric area requires splitting at the crossings and taking absolute values. Sketch first, integrate second.", "prereqs": ["g12.cal.integrals", "g11.geo.conic-sections"], "outcomes": ["Can sketch the region described by curves and lines before setting up any integral", "Can compute the area under a curve between two ordinates using a definite integral", "Can split an integral at x-axis crossings and combine absolute values to get true geometric area", "Can compute the area between two curves by integrating (upper − lower) between intersection points found algebraically"], "difficulty": 5, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g12.cal.differential-equations", "title": "Differential Equations: Separable and First-order Linear", "grade": 12, "strand": "cal", "description": "A differential equation relates a function to its derivatives — it describes how something changes and asks you to recover the thing itself. You will read off order and degree, solve separable equations by gathering each variable to its own side, and solve first-order linear equations dy/dx + P(x)y = Q(x) with the integrating factor e^∫P dx. General solutions carry arbitrary constants; initial conditions pin down particular solutions. This is the native language of physics, biology and economics: growth, decay, cooling, circuits, epidemics.", "prereqs": ["g12.cal.integrals"], "outcomes": ["Can determine the order and degree (when defined) of a differential equation", "Can verify that a given function is a solution of a differential equation", "Can solve separable equations, keeping the arbitrary constant and simplifying it legitimately", "Can solve dy/dx + P(x)y = Q(x) using the integrating factor e^∫P dx", "Can apply initial conditions to extract particular solutions and model growth/decay situations"], "difficulty": 5, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g12.vec.algebra", "title": "Vector Algebra: Dot and Cross Products", "grade": 12, "strand": "vec", "description": "Vectors carry magnitude and direction, and two different 'multiplications' extract different geometry: the dot product a·b = |a||b|cos θ is a SCALAR measuring alignment (zero means perpendicular), while the cross product a×b is a VECTOR perpendicular to both, with magnitude |a||b|sin θ equal to the parallelogram's area (zero means parallel). You will compute both in component form, find projections, angles, areas and unit normals. This is the working mathematics of forces, torques and 3D graphics.", "prereqs": ["g11.vec.intro-3d", "g11.tri.functions"], "outcomes": ["Can represent vectors in component form, compute magnitudes, unit vectors and section-formula combinations", "Can compute dot products, use them to find angles and projections, and characterise perpendicularity by a·b = 0", "Can compute cross products via the determinant rule, use |a×b| for areas, and characterise parallelism by a×b = 0", "Can state which product yields a scalar and which a vector, and that a×b = −(b×a) while a·b = b·a"], "difficulty": 4, "est_minutes": 90, "stub": false, "micros": []}, {"id": "g12.vec.3d-geometry", "title": "Three-Dimensional Geometry: Lines and Planes", "grade": 12, "strand": "vec", "description": "Vectors turn spatial geometry into computation: a line is r = a + λb (a point plus a direction), specified by direction ratios or the normalized direction cosines with l² + m² + n² = 1. You will find angles between lines using their direction vectors, the shortest distance between skew lines, and work with planes through their normal vectors — including the distance from a point to a plane. This is the geometry of flight paths, laser alignment and 3D modelling.", "prereqs": ["g12.vec.algebra", "g11.vec.intro-3d"], "outcomes": ["Can convert direction ratios to direction cosines by dividing by the magnitude, and verify l² + m² + n² = 1", "Can write vector and Cartesian equations of a line through a point with a given direction, or through two points", "Can compute the angle between two lines from their direction vectors and test parallel/perpendicular conditions", "Can find the shortest distance between skew lines and the distance from a point to a plane", "Can relate the angle between a line and a plane to the angle with the plane's normal (complementary angles)"], "difficulty": 5, "est_minutes": 105, "stub": false, "micros": []}, {"id": "g12.alg.linear-programming", "title": "Linear Programming", "grade": 12, "strand": "alg", "description": "Linear programming optimises a linear objective Z = ax + by subject to linear constraints: graph the inequalities, intersect them into a feasible region, and use the corner-point theorem — the optimum, if it exists, occurs at a vertex. Unbounded regions demand one extra check before declaring victory. Born from wartime logistics, LP now schedules airlines, blends diets, allocates factory time and routes deliveries.", "prereqs": ["g11.alg.linear-inequalities", "g11.geo.straight-lines"], "outcomes": ["Can translate a word problem into decision variables, a linear objective function and linear constraints", "Can graph the constraints and identify the feasible region, including non-negativity restrictions", "Can apply the corner-point method: find vertices, evaluate Z at each, and select the optimum", "Can handle unbounded regions correctly, checking whether the candidate optimum is genuine via the open half-plane test"], "difficulty": 3, "est_minutes": 60, "stub": false, "micros": []}, {"id": "g12.dat.probability", "title": "Probability: Conditional Probability, Bayes' Theorem, Random Variables", "grade": 12, "strand": "dat", "description": "Probability learns from information: P(A|B) re-weights chances given that B occurred, the multiplication rule chains events, and independence means P(A∩B) = P(A)P(B). Bayes' theorem reverses conditionals — from P(evidence|cause) to P(cause|evidence) — the logic behind medical testing and spam filters, where base rates routinely humiliate intuition. Random variables then attach numbers to outcomes, with probability distributions and means (expected values) to summarise them.", "prereqs": ["g11.dat.probability"], "outcomes": ["Can compute conditional probabilities from the definition P(A|B) = P(A∩B)/P(B) and from two-way tables", "Can apply the multiplication rule and test events for independence via P(A∩B) = P(A)P(B)", "Can distinguish independent events from mutually exclusive events with examples", "Can apply the total probability theorem and Bayes' theorem to reverse conditional probabilities", "Can construct the probability distribution of a discrete random variable and compute its mean (expected value)"], "difficulty": 5, "est_minutes": 120, "stub": false, "micros": []}]};
